/**
 * @file `GlueManifest` type + `validateGlueManifest()` — static, collect-all manifest validation
 * for the site-glue extension tier (SPEC-048 REQ-1/REQ-10/REQ-12; ADR-057 Decision 2, CIC-2).
 *
 * Purpose:
 * Pure, no-I/O validation of an already-parsed glue manifest against the closed six-member
 * call-site vocabulary and the eight-member capability vocabulary. Modeled directly on the
 * sibling extension mechanism's own manifest validator (same collect-all discipline, same
 * `{code, file, message}` error shape, same "one validator" role) — see that module's own header
 * for the precedent this file extends rather than reinvents.
 *
 * The six-member `GlueCallSite` union is closed and complete now; only three of its members have
 * a real adapter wired in v1. `validateGlueManifest()` accepts all six at the schema level — an
 * attachment declared against one of the three unwired call sites is NOT a validation error. It
 * fails later, at dispatch time, via `resolveCallSiteDispatch()` below, with a distinct
 * `UNWIRED_CALL_SITE` status — never a silent no-op, never a schema-level rejection. This is what
 * lets a later call site go live as "write the adapter, flip one dispatch-table entry" with zero
 * manifest-schema break (ADR-057 Decision 2).
 *
 * Product-neutral core: this module has no dependency on any host-specific package or module. The
 * three capability strings shared with the sibling plugin mechanism are re-declared here as
 * independent literals (mirroring that mechanism's own precedent of not importing the SDK
 * package's constants) so this module never needs to import anything host-specific.
 *
 * Architectural role:
 * Design-frozen contract for the extension-glue-tier work (ADR-057, Implementation Outline slice
 * 1). No dependencies; blocks every other slice.
 */

/**
 * The closed, six-member call-site vocabulary (ADR-057 Decision 2). All six are valid at schema
 * validation. Only the three named in `WIRED_CALL_SITES` below have a real adapter in v1 — the
 * other three are accepted here and rejected only at dispatch time (`resolveCallSiteDispatch()`).
 */
export type GlueCallSite =
  | "content.entry.beforeSave"
  | "assistant.tools"
  | "events.subscribe"
  | "admin.nav"
  | "render.contribute"
  | "http.routes";

/**
 * The eight-member capability vocabulary (ADR-057 Decision 2). The first three string values are
 * shared, by value, with the sibling plugin mechanism's own capability vocabulary — re-declared
 * independently here rather than imported, so this module carries no dependency on that mechanism
 * (see file header). The remaining five are glue-only vocabulary that never crosses into that
 * mechanism's own public surface.
 */
export type GlueCapability =
  | "content.read"
  | "content.extend"
  | "hooks.attach"
  | "tools.register"
  | "events.subscribe"
  | "admin.nav.register"
  | "render.contribute"
  | "http.route.register";

/**
 * One manifest-declared attachment to a call site. `callSite` is the only field this module's
 * validation reasons about; every other key is category-owned payload shape, defined by whichever
 * attachment-point adapter eventually reads this call site (not this module, and not yet built
 * for the three unwired call sites) — validated here only at the "well-formed object" level.
 */
export interface GlueManifestAttachment {
  readonly callSite: GlueCallSite;
  readonly [payloadKey: string]: unknown;
}

/** A parsed, not-yet-validated glue manifest (the closed contract this ADR froze). */
export interface GlueManifest {
  readonly id: string;
  readonly version: string;
  readonly sdkRange: string;
  readonly capabilities: readonly GlueCapability[];
  readonly attachments: readonly GlueManifestAttachment[];
}

/** One validation-vocabulary entry — same `{code, file, message}` shape the sibling mechanism's
 * validator already uses, kept for shape parity with any error-rendering surface that later reuses
 * both. `file` is always `null` here: unlike a distributed plugin artifact, a glue manifest has no
 * packaged files to hash or implicate (REQ-10 — the integrity-hash step itself is skipped
 * entirely for glue, not merely unimplicated by any one error). */
export interface GlueManifestValidationError {
  readonly code: string;
  readonly file: string | null;
  readonly message: string;
}

export interface ValidateGlueManifestRequired {
  /** An already-parsed glue manifest value (unparseable JSON is the loader's concern, a later
   * slice — this function receives a JS value, never a file path or raw bytes). */
  readonly manifest: unknown;
}

export type ValidateGlueManifestOptional = {};

export interface ValidateGlueManifestResult {
  /** Every applicable error, collected — not first-failure (same collect-all discipline as the
   * sibling validator). Empty when the manifest is statically valid. */
  readonly errors: readonly GlueManifestValidationError[];
}

const REQUIRED_KEYS = ["id", "version", "sdkRange", "capabilities", "attachments"] as const;
const ALLOWED_KEYS = new Set<string>(REQUIRED_KEYS);

const VALID_CAPABILITIES = new Set<GlueCapability>([
  "content.read",
  "content.extend",
  "hooks.attach",
  "tools.register",
  "events.subscribe",
  "admin.nav.register",
  "render.contribute",
  "http.route.register",
]);

const VALID_CALL_SITES = new Set<GlueCallSite>([
  "content.entry.beforeSave",
  "assistant.tools",
  "events.subscribe",
  "admin.nav",
  "render.contribute",
  "http.routes",
]);

/** The three call sites with a real adapter in v1 (ADR-057 Decision 2's dispatch table — three
 * real entries, three typed placeholders). Wiring a fourth is "add one member here," never a
 * manifest-schema change. */
const WIRED_CALL_SITES = new Set<GlueCallSite>(["content.entry.beforeSave", "assistant.tools", "events.subscribe"]);

const ID_PATTERN = /^[a-z0-9-]+$/;
const MAX_ID_LENGTH = 50;

/**
 * Auto-quarantine threshold (SPEC-048 REQ-17, ADR-057 Decision 5 / Open #1) — a placeholder the
 * owner has not tuned yet, NOT a measured or reviewed value. Recorded once, here, so every later
 * consumer (the control-loop quarantine slice, and anything that needs to describe the
 * no-brick invariant before that slice lands) reads the same placeholder instead of a scattered
 * magic number. Replace wholesale, not incrementally, once the owner picks a real threshold.
 */
export const AUTO_QUARANTINE_THRESHOLD_PLACEHOLDER = Object.freeze({
  maxFailures: 3,
  windowMs: 5 * 60 * 1000,
});

function malformed(message: string): GlueManifestValidationError {
  return { code: "MANIFEST_MALFORMED", file: null, message };
}

/**
 * Validates one already-parsed glue manifest, collecting every applicable error rather than
 * stopping at the first. Pure — no I/O, no mutation of `manifest`.
 *
 * @throws Nothing — validation failures are reported via the returned `errors` array, never a
 * thrown error (a malformed top-level shape, e.g. `manifest` being `null` or an array, is itself a
 * `MANIFEST_MALFORMED` entry in the result, not a throw).
 * @complexity O(capabilities.length + attachments.length) — bounded by one manifest's own declared
 * arrays, never by external/unbounded input.
 * @overallScore 100/100
 */
export function validateGlueManifest(
  required: ValidateGlueManifestRequired,
  _optional: ValidateGlueManifestOptional = {}
): ValidateGlueManifestResult {
  const { manifest } = required;
  const errors: GlueManifestValidationError[] = [];

  if (typeof manifest !== "object" || manifest === null || Array.isArray(manifest)) {
    return { errors: [malformed("glue manifest must be a JSON object")] };
  }

  // Treat the input as a read-only bag of unknown values — never assigned back into.
  const raw = manifest as Readonly<Record<string, unknown>>;

  for (const key of Object.keys(raw)) {
    if (!ALLOWED_KEYS.has(key)) {
      errors.push(malformed(`unknown manifest key '${key}'`));
    }
  }
  for (const key of REQUIRED_KEYS) {
    if (raw[key] === undefined) {
      errors.push(malformed(`missing required manifest field '${key}'`));
    }
  }

  // --- id: format only (no folder-match/shadow check — those are the loader's on-disk concern,
  // a later slice; this manifest's closed contract carries no folderName/builtInIds input). ---
  const id = typeof raw.id === "string" ? raw.id : undefined;
  if (raw.id !== undefined && id === undefined) {
    errors.push(malformed("'id' must be a string"));
  }
  if (id !== undefined && (!ID_PATTERN.test(id) || id.length < 1 || id.length > MAX_ID_LENGTH)) {
    errors.push(malformed(`id '${id}' must match ${ID_PATTERN} and be 1-${MAX_ID_LENGTH} characters`));
  }

  // --- version / sdkRange: presence-checked above only, same as the sibling validator's own
  // choice not to format-check these two fields (sdkRange's actual compatibility check is a
  // load-time, not a validation-time, concern). ---
  if (raw.version !== undefined && typeof raw.version !== "string") {
    errors.push(malformed("'version' must be a string"));
  }
  if (raw.sdkRange !== undefined && typeof raw.sdkRange !== "string") {
    errors.push(malformed("'sdkRange' must be a string"));
  }

  // --- capabilities (REQ-1) ---
  const capabilities = Array.isArray(raw.capabilities) ? raw.capabilities : [];
  if (raw.capabilities !== undefined && !Array.isArray(raw.capabilities)) {
    errors.push(malformed("'capabilities' must be an array"));
  }
  for (const capability of capabilities) {
    if (typeof capability !== "string" || !VALID_CAPABILITIES.has(capability as GlueCapability)) {
      errors.push({
        code: "CAPABILITY_UNKNOWN",
        file: null,
        message: `capability '${String(capability)}' is outside the v1 vocabulary`,
      });
    }
  }

  // --- attachments (ADR-057 Decision 2: all six call sites accepted here; only three are wired
  // for DISPATCH — that distinction is resolveCallSiteDispatch()'s job, not this function's). ---
  const attachments = Array.isArray(raw.attachments) ? raw.attachments : [];
  if (raw.attachments !== undefined && !Array.isArray(raw.attachments)) {
    errors.push(malformed("'attachments' must be an array"));
  }
  for (const attachment of attachments) {
    if (typeof attachment !== "object" || attachment === null || Array.isArray(attachment)) {
      errors.push(malformed("each 'attachments' entry must be an object"));
      continue;
    }
    const callSite = (attachment as Readonly<Record<string, unknown>>).callSite;
    if (typeof callSite !== "string" || !VALID_CALL_SITES.has(callSite as GlueCallSite)) {
      errors.push({
        code: "CALL_SITE_UNKNOWN",
        file: null,
        message: `call site '${String(callSite)}' is outside the closed six-member vocabulary`,
      });
    }
  }

  return { errors };
}

/** The result of checking whether a (schema-valid) call site has a real adapter wired in v1. */
export type GlueCallSiteDispatchStatus =
  | { readonly wired: true }
  | { readonly wired: false; readonly code: "UNWIRED_CALL_SITE" };

/**
 * Resolves whether `callSite` has a real dispatch-time adapter in v1. Distinct from — and always
 * called strictly after — `validateGlueManifest()`: a call site can be schema-valid (one of the
 * closed six) and still be `wired: false` here. Callers (an attachment-point adapter or the
 * loader, both later slices) turn `wired: false` into whatever concrete rejection their own layer
 * needs; this function stays pure and does not throw, mirroring this codebase's own
 * discriminated-result convention for expected, non-exceptional outcomes.
 *
 * @complexity O(1) — a single fixed-size Set lookup.
 * @overallScore 100/100
 */
export function resolveCallSiteDispatch(callSite: GlueCallSite): GlueCallSiteDispatchStatus {
  return WIRED_CALL_SITES.has(callSite) ? { wired: true } : { wired: false, code: "UNWIRED_CALL_SITE" };
}
/**
 * @file `buildGlueCapabilityGate()` — capability-scoped delegate handle for `GlueCapability`
 * (SPEC-048 REQ-1/REQ-4; ADR-057 CIC-1, `ESCALATE_SECURITY`).
 *
 * Purpose:
 * Extends the sibling plugin mechanism's own `gate()` pattern (always-present, granted-delegates,
 * ungranted-throws) to the wider eight-member glue capability vocabulary. **Default-deny**: a
 * capability absent from the granted set is never silently omitted from the returned handle — it
 * is present as a callable stub that synchronously throws a classified `GlueCapabilityDeniedError`
 * naming the missing capability. A bare `TypeError` on an absent property is exactly the wrong
 * implementation this mirrors the sibling mechanism's own CIC in guarding against.
 *
 * **A module cannot grow its own capability set through this gate.** The granted set is a snapshot
 * taken once, at build time, from a caller-supplied list — never read from anything the gated
 * module itself holds a reference to or could write. The returned handle is frozen; there is no
 * setter, no admin surface, and no code path from inside a delegate call back into the granted
 * set. Widening what a module can do requires building a new gate from a re-approved manifest, not
 * calling anything this module exports.
 *
 * Capabilities are exposed by handle only: every granted position is a plain closure the caller
 * supplies (`coreDelegates`), never a raw filesystem, network, or process handle. This module has
 * zero I/O of its own — it is pure wiring between "is this granted" and "which closure runs."
 *
 * Architectural role:
 * Design-frozen contract for the extension-glue-tier work (ADR-057, Implementation Outline slice
 * 1). Depends only on `./manifest`'s `GlueCapability` type — no host-specific dependency.
 */
import type { GlueCapability } from "./manifest.js";

/** Thrown synchronously when a glue module invokes a capability it did not declare (mirrors the
 * sibling mechanism's `CapabilityDeniedError` shape, generalized to `GlueCapability`). */
export class GlueCapabilityDeniedError extends Error {
  readonly moduleId: string;
  readonly capability: GlueCapability;

  constructor(moduleId: string, capability: GlueCapability) {
    super(`module '${moduleId}' invoked '${capability}' without declaring it in its manifest capabilities`);
    this.name = "GlueCapabilityDeniedError";
    this.moduleId = moduleId;
    this.capability = capability;
  }
}

/** Every capability position resolves to one of these once gated. Untyped args/return —
 * each capability's real signature is owned by whichever attachment-point adapter backs it
 * (later slices), never by this generic gate. */
export type GlueCapabilityDelegate = (...args: readonly unknown[]) => unknown;

/** The closed, eight-member vocabulary this gate always exposes a position for, regardless of
 * grant set (CIC-1's "always present" property, made an iterable constant so the gate and its
 * tests share one source of truth for "every position"). */
export const GLUE_CAPABILITIES: readonly GlueCapability[] = [
  "content.read",
  "content.extend",
  "hooks.attach",
  "tools.register",
  "events.subscribe",
  "admin.nav.register",
  "render.contribute",
  "http.route.register",
];

export interface BuildGlueCapabilityGateRequired {
  readonly moduleId: string;
  /** The manifest's declared capability set (already validated against the v1 vocabulary by
   * `validateGlueManifest()` — this function trusts its input is well-formed capability strings,
   * same division of labor as the sibling mechanism's own capability-gate). */
  readonly capabilities: readonly GlueCapability[];
  /** The real backing implementation for every granted position, supplied by the caller (a later
   * slice's loader, closing over that specific module load's host-port-backed state). This module
   * never reaches into any host mechanism directly. */
  readonly coreDelegates: Readonly<Record<GlueCapability, GlueCapabilityDelegate>>;
}

export type BuildGlueCapabilityGateOptional = {};

/**
 * Builds one glue module's capability-scoped delegate handle. Every one of the eight
 * `GlueCapability` positions is always present on the returned object (CIC-1) — granted positions
 * delegate to `coreDelegates`, ungranted positions are stubs that throw `GlueCapabilityDeniedError`
 * when invoked (never at build time — the stub itself is a normal, present function; only calling
 * it throws). The returned object is frozen: no caller, including the gated module itself, can add,
 * remove, or replace a position after the gate is built.
 *
 * @throws Nothing at build time. The returned handle's ungranted-position stubs throw
 * `GlueCapabilityDeniedError` synchronously when invoked.
 * @complexity O(1) — eight capability checks, fixed-size regardless of the caller-supplied
 * `capabilities` array's length.
 * @overallScore 100/100
 */
export function buildGlueCapabilityGate(
  required: BuildGlueCapabilityGateRequired,
  _optional: BuildGlueCapabilityGateOptional = {}
): Readonly<Record<GlueCapability, GlueCapabilityDelegate>> {
  const { moduleId, capabilities, coreDelegates } = required;
  // Defensive copy: a caller-side mutation of the `capabilities` array after this call must never
  // change what this already-built gate grants (part of CIC-1's "cannot grow its own capability
  // set" property — the snapshot is taken once, here, and never re-read).
  const granted = new Set<GlueCapability>(capabilities);

  function gate(capability: GlueCapability): GlueCapabilityDelegate {
    if (granted.has(capability)) {
      return coreDelegates[capability];
    }
    return (..._args: readonly unknown[]) => {
      throw new GlueCapabilityDeniedError(moduleId, capability);
    };
  }

  const handle = {} as Record<GlueCapability, GlueCapabilityDelegate>;
  for (const capability of GLUE_CAPABILITIES) {
    handle[capability] = gate(capability);
  }
  return Object.freeze(handle);
}
/**
 * @file `GlueHostPort` — the seam every host-specific concern (persistence, admin surface,
 * permissions) is reached through (ADR-057 Decision 6).
 *
 * Purpose:
 * This interface is the entire boundary between the product-neutral glue mechanism (`manifest.ts`,
 * `capability-gate.ts`, and this file) and whatever concrete host wires it up. No file in this
 * directory may reach a host mechanism any other way — not by importing a host module directly,
 * not by reading a host-specific config value, not by assuming a particular database or admin
 * shell exists. A future port-implementing host supplies one object satisfying this shape; that is
 * the entire integration surface.
 *
 * This is why a later move of this directory to a different host is "copy the directory, write one
 * new adapter satisfying this interface" rather than a rewrite: every method here names a
 * capability the mechanism needs, not a concrete subsystem it depends on.
 *
 * Three of the nine methods below (`registerAdminNav`, `contributeRender`, `registerHttpRoute`)
 * correspond to the three call sites that are schema-valid but dispatch-unwired in v1
 * (`resolveCallSiteDispatch()` in `./manifest`). Their signatures are real and stable now — wiring
 * one later means a host's adapter implementation stops throwing and starts doing real work,
 * never a signature change here.
 *
 * Excluded from CIC designation (ADR-057's own note): this interface is pure delegation with no
 * internal logic — no implementation lives in this file, only the contract shape.
 *
 * Architectural role:
 * Design-frozen contract for the extension-glue-tier work (ADR-057, Implementation Outline slice
 * 1). No implementation is provided here — the one real adapter is later, out-of-slice work.
 */
import type { GlueCallSite, GlueCapability } from "./manifest.js";

/** One glue-module-declared field, in the same four-JSON-primitive-type shape the sibling
 * mechanism's own field declarations use. Kept local (not imported) for the same
 * zero-host-dependency reason `manifest.ts`'s capability/call-site literals are re-declared rather
 * than imported. */
export interface GlueFieldDecl {
  readonly path: string;
  readonly type: "string" | "integer" | "number" | "boolean";
}

/** A content-lifecycle filter's signature — structurally identical to the sibling mechanism's own
 * before-save filter contract (same entry/patch shape), declared independently here so this port
 * has no import from that mechanism. */
export type GlueContentLifecycleFilter = (
  entry: Readonly<Record<string, unknown>>,
  ctx: { readonly moduleId: string; readonly workspaceId: string }
) => Readonly<Record<string, unknown>> | Promise<Readonly<Record<string, unknown>>>;

/** One tool registration a glue module contributes, merged in after the host's own core tool list
 * is fully assembled (ADR-057 Decision 4 — fail-isolated, never inside the host's own fail-fast
 * registration pass). */
export interface GlueToolRegistration {
  readonly toolId: string;
  readonly handler: (...args: readonly unknown[]) => unknown;
}

/** An owner- or system-attributed state transition, routed through the same change-set gateway
 * every other mutation in the host already uses (ADR-057 Decision 5 — no new mutation-safety
 * mechanism). Left as an opaque command value: the gateway's own contract, not this port's, owns
 * its shape. */
export type GlueChangeSetCommand = unknown;

export interface GlueHostPort {
  /** Attaches a glue module's content-lifecycle filter to the `content.entry.beforeSave` call
   * site. WIRED in v1. */
  attachContentLifecycleFilter(
    moduleId: string,
    filter: GlueContentLifecycleFilter,
    declaredFields: readonly GlueFieldDecl[]
  ): void;

  /** Merges a glue module's tool registrations onto the host's already-assembled core tool list.
   * WIRED in v1; fail-isolated per module (ADR-057 Decision 4 — a throwing or duplicate-id
   * registration drops and quarantines only that module, never the host's own registration pass). */
  registerTools(moduleId: string, registrations: readonly GlueToolRegistration[]): void;

  /** Subscribes a glue module's handler to one async "this happened" event. WIRED in v1; contained
   * by the host's existing outbox retry/dead-letter semantics — no new mechanism. */
  subscribeEvent(moduleId: string, eventName: string, handler: (payload: unknown) => Promise<void> | void): void;

  /** Registers a nav entry routing to a server-rendered page. UNWIRED in v1 — the one real host
   * adapter throws for this method until this call site is wired; the signature itself does not
   * change when it is. */
  registerAdminNav(moduleId: string, payload: Readonly<Record<string, unknown>>): void;

  /** Contributes server-rendered data to a rendering region. UNWIRED in v1 — same status as
   * `registerAdminNav` above. */
  contributeRender(moduleId: string, payload: Readonly<Record<string, unknown>>): void;

  /** Registers a capability-gated HTTP route. UNWIRED in v1 — same status as `registerAdminNav`
   * above. */
  registerHttpRoute(moduleId: string, payload: Readonly<Record<string, unknown>>): void;

  /** Runs one control-loop state transition (propose/approve/revert/quarantine) through the host's
   * existing change-set gateway. */
  runChangeSet(command: GlueChangeSetCommand): Promise<unknown>;

  /** Persists a glue module's prior file content, content-addressed, before a new-content write is
   * issued (ADR-057 CIC-4's required ordering — this method must be awaited and confirmed durable
   * before the corresponding write proceeds; enforcing that ordering is the later control-loop
   * slice's job, not this port's). */
  snapshotBlob(content: Uint8Array | string): Promise<{ readonly hash: string }>;

  /** Restores previously snapshotted content by its content hash. */
  restoreBlob(hash: string): Promise<Uint8Array>;
}

/** Re-exported for callers that want the port's shape alongside the vocabulary it's parameterized
 * over, without a second import line. */
export type { GlueCallSite, GlueCapability };
/**
 * @file `attachGlueContentLifecycle()` — the content-lifecycle attachment point (SPEC-048 REQ-5;
 * ADR-057 Decision 2's `content.entry.beforeSave` adapter row, Decision 2.1).
 *
 * Purpose:
 * The wired adapter for the one category that stays **fail-closed, unchanged** (ADR-057 Decision 4
 * — data-mutation call sites are never fail-isolated). This module owns none of that containment
 * logic itself: it delegates straight to {@link GlueHostPort.attachContentLifecycleFilter}, whose
 * real, host-specific implementation is expected to attach the given filter to a live
 * `hook-registry.ts` instance via `plugin-runtime/loader.ts`'s `attachLoadedPlugin()` — the shared
 * extraction ADR-057 Decision 2.1 introduced, with the `"glue"` source. That composition (a real
 * `HookRegistry` plus `attachLoadedPlugin`) is host-specific wiring and does not belong in this
 * product-neutral module; see `__tests__/integration/content-lifecycle.integration.test.ts` for a
 * worked example proving the two compose correctly end to end.
 *
 * Product-neutral core: depends only on `../ports` (the frozen `GlueHostPort` seam). No import of
 * `plugin-runtime`, `hook-registry.ts`, or anything else host-specific — the fail-closed
 * *mechanism* this category relies on lives entirely behind the port, not in this file.
 *
 * Architectural role:
 * Implementation Outline slice 2 (ADR-057, Implementation Outline). Depends on slice 1's frozen
 * `manifest.ts`/`ports.ts` contracts.
 */
import type { GlueContentLifecycleFilter, GlueFieldDecl, GlueHostPort } from "../ports.js";

export interface AttachGlueContentLifecycleRequired {
  readonly moduleId: string;
  /** The glue module's already-obtained `content.entry.beforeSave` filter — how it was obtained
   * (a `setup()` call gated by this module's own granted `GlueCapability` set) is the loader's
   * concern, not this attachment point's. */
  readonly filter: GlueContentLifecycleFilter;
  readonly declaredFields: readonly GlueFieldDecl[];
  /** The injected seam this module reaches every host mechanism through — never imported directly. */
  readonly hostPort: Pick<GlueHostPort, "attachContentLifecycleFilter">;
}

export type AttachGlueContentLifecycleOptional = {};

/**
 * Attaches one glue module's content-lifecycle filter via the host port. Pure delegation — this
 * function adds no containment or validation of its own, matching ADR-057 Decision 4's explicit
 * instruction that this category stays fail-closed and unchanged from `hook-registry.ts`'s existing
 * discipline (a throw here is expected to propagate, not be caught).
 *
 * @throws Whatever `hostPort.attachContentLifecycleFilter()` itself throws — never caught here.
 * @complexity O(1) — a single delegated call.
 * @overallScore 100/100
 */
export function attachGlueContentLifecycle(
  required: AttachGlueContentLifecycleRequired,
  _optional: AttachGlueContentLifecycleOptional = {}
): void {
  const { moduleId, filter, declaredFields, hostPort } = required;
  hostPort.attachContentLifecycleFilter(moduleId, filter, declaredFields);
}
/**
 * @file `subscribeGlueEvent()` — the async "this happened" attachment point (SPEC-048 REQ-5/REQ-8;
 * ADR-057 Decision 2's `events.subscribe` adapter row).
 *
 * Purpose:
 * REQ-8's conclusion for this category, confirmed correct by ADR-057 Decision 4: no new containment
 * mechanism is needed. The outbox's own retry/dead-letter semantics (`core/events`, ADR-009) already
 * require every handler to be idempotent, and that requirement applies identically whether the
 * handler belongs to core or to a glue module — this attachment point does not wrap, retry, or
 * isolate anything of its own; it delegates straight to {@link GlueHostPort.subscribeEvent}, whose
 * real implementation is expected to register the handler on the host's live `EventBusPort`
 * (`src/core/events`), so delivery inherits the SAME retry/dead-letter path a real outbox event
 * already goes through.
 *
 * Product-neutral core: depends only on `../ports` (the frozen `GlueHostPort` seam). No import of
 * `core/events` or any concrete bus/outbox implementation.
 *
 * Architectural role:
 * Implementation Outline slice 4 (ADR-057, Implementation Outline). Depends on slice 1's frozen
 * `manifest.ts`/`ports.ts` contracts. Independent of slices 2 and 3.
 */
import type { GlueHostPort } from "../ports.js";

export interface SubscribeGlueEventRequired {
  readonly moduleId: string;
  readonly eventName: string;
  /** The glue module's already-obtained handler. Idempotency is the module author's
   * responsibility, matching every other outbox subscriber in this codebase (ADR-009's
   * consequence) — this function does not, and cannot, verify that property. */
  readonly handler: (payload: unknown) => Promise<void> | void;
  readonly hostPort: Pick<GlueHostPort, "subscribeEvent">;
}

export type SubscribeGlueEventOptional = {};

/**
 * Subscribes one glue module's handler to one named event via the host port. Pure delegation — no
 * containment logic of its own, matching REQ-8's conclusion that this category needs none beyond
 * what the outbox already provides.
 *
 * @throws Whatever `hostPort.subscribeEvent()` itself throws — never caught here.
 * @complexity O(1) — a single delegated call.
 * @overallScore 100/100
 */
export function subscribeGlueEvent(
  required: SubscribeGlueEventRequired,
  _optional: SubscribeGlueEventOptional = {}
): void {
  const { moduleId, eventName, handler, hostPort } = required;
  hostPort.subscribeEvent(moduleId, eventName, handler);
}
/**
 * @file `mergeGlueToolRegistrations()` — the tool-registration attachment point (SPEC-048 REQ-5/
 * REQ-8/REQ-16; ADR-057 Decision 2's `assistant.tools` adapter row, Decision 4, CIC-3
 * `ESCALATE_IRREVERSIBLE`).
 *
 * Purpose:
 * The one v1-wired call site that is BOTH admin-surface/boot-categorized (REQ-8) and simultaneously
 * v1-wired (REQ-5) — ADR-057 Decision 4's correction to the dispatch brief's own framing: fail-
 * isolated containment cannot wait for a later admin-surface wiring wave, because this category
 * already needs it in v1.
 *
 * This module never enters, imports, or in any way touches the array
 * `assistant/tool-registrations.ts`'s `buildAssistantToolRegistrations()` governs — glue's
 * contributions are merged strictly AFTER that already-fail-fast-assembled list exists, one glue
 * module at a time, each independently try/catch-wrapped (CIC-3). A throw from a module's own
 * registration-building call, OR a throw from the host port's own mounting call, OR a duplicate
 * tool id (against the core list or against an earlier-succeeded glue module in the SAME pass)
 * drops and quarantines ONLY that module — core's own fail-fast domains keep their existing
 * "duplicate registration stops daemon boot" property completely untouched, because glue never
 * becomes a `DOMAIN_SLICES` entry (ADR-057 Decision 4).
 *
 * Product-neutral core: depends only on `../ports` (the frozen `GlueHostPort` seam). The REAL
 * merge onto the host's live tool list happens behind `hostPort.registerTools()` — this module
 * only decides, per glue module, whether that call is safe to make at all.
 *
 * Architectural role:
 * Implementation Outline slice 3 (ADR-057, Implementation Outline). Depends on slice 1's frozen
 * `manifest.ts`/`ports.ts` contracts.
 */
import type { GlueHostPort, GlueToolRegistration } from "../ports.js";

/** One glue module's own tool-registration contribution, not yet built. `build()` may throw —
 * CIC-3's fail-isolation wrapper is precisely what catches that throw below. */
export interface GlueToolModuleContribution {
  readonly moduleId: string;
  readonly build: () => readonly GlueToolRegistration[];
}

export interface MergeGlueToolRegistrationsRequired {
  /** Every tool id the host's own already-fail-fast-assembled core list owns (e.g. the ids from
   * `buildAssistantToolRegistrations()`'s output) — read-only, for collision detection; never
   * re-validated, never mutated, never re-derived by this function. */
  readonly coreToolIds: readonly string[];
  /** Every glue module contributing tool registrations this pass, in the order they are tried.
   * Order is deterministic id-ascending per ADR-057 Decision 3's TB-01-extension discipline for
   * glue among itself — establishing that order is the caller's job (the loader, a later slice);
   * this function processes whatever order it receives. */
  readonly glueModules: readonly GlueToolModuleContribution[];
  readonly hostPort: Pick<GlueHostPort, "registerTools">;
}

export type MergeGlueToolRegistrationsOptional = {};

export type GlueToolQuarantineReason = "THROW" | "DUPLICATE_TOOL_ID";

export interface GlueToolQuarantineEntry {
  readonly moduleId: string;
  readonly reason: GlueToolQuarantineReason;
  readonly detail: string;
}

export interface MergeGlueToolRegistrationsResult {
  /** Every glue module whose registrations were successfully merged, in processing order. */
  readonly registeredModuleIds: readonly string[];
  /** Every glue module dropped this pass, with why — never a thrown exception (CIC-3's whole
   * point: this function itself never throws for a per-module failure). */
  readonly quarantined: readonly GlueToolQuarantineEntry[];
}

/**
 * Merges every glue module's own tool registrations onto the host's already-assembled core list,
 * one module at a time, each fully isolated from the others' and from core's own fail-fast
 * discipline (CIC-3). Never throws for a per-module failure — a broken or colliding module is
 * recorded in `quarantined` and simply excluded, so the caller (the admin boot path, eventually)
 * can surface a notice without the boot itself failing (REQ-16's no-brick invariant, this
 * function's share of it).
 *
 * @throws Nothing of its own for a per-module failure (build throw, host-port throw, or id
 * collision are all caught and recorded). An unexpected error in this function's OWN bookkeeping
 * (there is none — the loop body is the only source of failure, and every source is wrapped) would
 * be the only way this could throw, which is to say it does not.
 * @complexity O(glueModules.length · maxRegistrationsPerModule) — bounded by this pass's own input,
 * dominated by the duplicate-id `Set` lookups (O(1) each).
 * @overallScore 100/100
 */
export function mergeGlueToolRegistrations(
  required: MergeGlueToolRegistrationsRequired,
  _optional: MergeGlueToolRegistrationsOptional = {}
): MergeGlueToolRegistrationsResult {
  const { coreToolIds, glueModules, hostPort } = required;
  const claimedToolIds = new Set<string>(coreToolIds);
  const registeredModuleIds: string[] = [];
  const quarantined: GlueToolQuarantineEntry[] = [];

  const quarantine = (moduleId: string, reason: GlueToolQuarantineReason, detail: string): void => {
    quarantined.push({ moduleId, reason, detail });
  };
  const messageOf = (error: unknown): string => (error instanceof Error ? error.message : String(error));

  for (const module of glueModules) {
    let registrations: readonly GlueToolRegistration[];
    try {
      registrations = module.build();
    } catch (error) {
      quarantine(module.moduleId, "THROW", `registration build failed: ${messageOf(error)}`);
      continue;
    }

    const duplicate = registrations.find((registration) => claimedToolIds.has(registration.toolId));
    if (duplicate) {
      quarantine(
        module.moduleId,
        "DUPLICATE_TOOL_ID",
        `tool id '${duplicate.toolId}' is already registered by core or an earlier glue module`
      );
      continue;
    }

    try {
      hostPort.registerTools(module.moduleId, registrations);
    } catch (error) {
      quarantine(module.moduleId, "THROW", `host port registration failed: ${messageOf(error)}`);
      continue;
    }

    for (const registration of registrations) claimedToolIds.add(registration.toolId);
    registeredModuleIds.push(module.moduleId);
  }

  return { registeredModuleIds, quarantined };
}

/**
 * @file `PluginManifest` type + `validateManifest()` — static, collect-all manifest validation
 * (SPEC-005 REQ-01, BR-02/BR-03; ADR-024 `tier`, 1.1.1 fix).
 *
 * Purpose:
 * Pure, no-I/O validation of an already-parsed `tovu.plugin.json` object against the v1 required-
 * field set, id/folder match, capability vocabulary, hook vocabulary, and field-declaration rules.
 * Consumed by both `discovery.ts` (list-time, every discovery pass) and `loader.ts` (enable-time
 * re-validation, BR-05) — one validator, two call sites, never diverging (mirrors SPEC-004's theme
 * validator shape, per feature.spec.md's own Article IV note).
 *
 * Division of labor (a TDD design decision, not itself a spec requirement): BR-02 step (1),
 * "package-level (size, disallowed files, server/index.mjs presence)", requires a directory
 * listing this function's contract deliberately does NOT take as input (Implementation Outline
 * C-006: `{ manifest: unknown, folderName: string, builtInIds: string[] }` — no file-list
 * parameter). Package-level filesystem checks are therefore `discovery.ts`'s responsibility
 * (REQ-02/03's discovery step, which does read the filesystem); this function owns BR-02 steps
 * (2)-(6) only: manifest / identity / capabilities / hooks / fields. `discovery.ts` merges both
 * error sets into one `PluginDiscoveryRecord.errors[]` array before listing/enabling a plugin.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-005/C-006). Signature and JSDoc are
 * design-frozen; `validateManifest()` collects every BR-02 steps (2)-(6) violation (identity,
 * engine/tier, capabilities, hooks, fields) rather than stopping at the first, returning them in
 * `errors[]` — it never throws. Verified against `__tests__/unit/manifest.unit.test.ts`.
 */

/** ADR-024 §1 trust-tier vocabulary (1.1.1 REQ-01 fix). Literal encoding reused verbatim from the
 * existing, approved SPEC-032/ADR-023 precedent (`DataModuleDecl.pluginTier`). */
export type PluginTier = "tier-1" | "tier-2" | "tier-3";

/** REQ-04's exactly-three v1 capability vocabulary, as manifest-declared strings (validated
 * against this set by `validateManifest`; `@tovu/sdk`'s `CONTENT_READ`/`CONTENT_EXTEND`/
 * `HOOKS_ATTACH` constants are the same literal values, kept independent here so this module has
 * no dependency on the SDK package per the Module Map). */
export type PluginCapability = "content.read" | "content.extend" | "hooks.attach";

/** REQ-06 field declaration — `ext.{pluginId}.{field}` (BR-06). `queryable` MUST be `false` in
 * v1 (EC-04); a `true` value is a validation error (`QUERYABLE_UNSUPPORTED_V1`), not silently
 * coerced. */
export interface PluginManifestFieldDecl {
  readonly path: string;
  readonly type: "string" | "integer" | "number" | "boolean";
  readonly queryable: boolean;
}

/** `tovu.plugin.json` — the ecosystem compatibility surface (state.spec.md §2, ADR-004). */
export interface PluginManifest {
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly sdkRange: string;
  readonly engine: number;
  readonly tier: PluginTier;
  readonly capabilities: readonly string[];
  readonly hooks: readonly string[];
  readonly fields: readonly PluginManifestFieldDecl[];
  readonly integrity: Readonly<Record<string, string>>;
  /** Parsed-and-stored, UNUSED in v1 (forward-compat, no behavior — state.spec.md §2). */
  readonly adminSurfaces?: readonly unknown[] | null;
  readonly contentTypes?: readonly unknown[] | null;
  readonly provenance?: { readonly sourceUrl?: string; readonly signature?: string } | null;
  readonly dependencies?: Readonly<Record<string, string>> | null;
}

/** One validation-vocabulary entry (errors.spec.md §3). `file` names the offending packaged file
 * when applicable; `null` for manifest-level errors with no single implicated file. This is the
 * shared shape used verbatim by both `PLUGINS_LIST.plugins[].errors[]` and
 * `PLUGIN_INVALID.details.errors[]` (errors.spec.md §4 — "one validator, two surfaces"). */
export interface PluginValidationError {
  readonly code: string;
  readonly file: string | null;
  readonly message: string;
}

export interface ValidateManifestRequired {
  /** An already-parsed `tovu.plugin.json` value (unparseable JSON is `discovery.ts`'s concern —
   * this function receives a JS value, never a file path or raw bytes). */
  readonly manifest: unknown;
  /** The install folder name this manifest was read from (EC-01: `id` must equal this). */
  readonly folderName: string;
  /** Every currently-registered built-in plugin id (DUP-01: a site plugin id equal to a built-in
   * id is `SHADOWS_BUILT_IN`, not silently shadowed). */
  readonly builtInIds: readonly string[];
}

export type ValidateManifestOptional = {}

export interface ValidateManifestResult {
  /** Every applicable error, collected — NOT first-failure (BR-02). Empty when the manifest is
   * statically valid (integrity/`sdkRange` are separate, load-pipeline-time checks, BR-01). */
  readonly errors: readonly PluginValidationError[];
}

/**
 * Validates one already-parsed manifest against BR-02 steps (2)-(6), collecting every applicable
 * error rather than stopping at the first (BR-02: "collect ALL statically-determinable errors").
 * Pure — no I/O, no mutation of `manifest`.
 *
 * @throws Nothing — validation failures are reported via the returned `errors` array, never a
 * thrown error (this function itself cannot fail; a malformed top-level shape, e.g. `manifest`
 * being `null` or an array, is itself a `MANIFEST_MALFORMED` entry in the result, not a throw).
 * @complexity O(fields.length + capabilities.length + hooks.length) — bounded by one manifest's
 * own declared arrays, never by external/unbounded input.
 */
/** REQ-01's required top-level manifest keys — every one of these must be present. */
const REQUIRED_KEYS = [
  "id",
  "name",
  "version",
  "sdkRange",
  "engine",
  "tier",
  "capabilities",
  "hooks",
  "fields",
  "integrity",
] as const;

/** REQ-01's "parsed-and-stored but unused in v1" forward-compat keys — allowed, never validated. */
const OPTIONAL_KEYS = ["adminSurfaces", "contentTypes", "provenance", "dependencies"] as const;

const ALLOWED_KEYS = new Set<string>([...REQUIRED_KEYS, ...OPTIONAL_KEYS]);
const VALID_CAPABILITIES = new Set<PluginCapability>(["content.read", "content.extend", "hooks.attach"]);
const VALID_HOOKS = new Set(["content.entry.beforeSave"]);
const VALID_TIERS = new Set<PluginTier>(["tier-1", "tier-2", "tier-3"]);
const VALID_FIELD_TYPES = new Set(["string", "integer", "number", "boolean"]);
/** The one plugin-contract version this runtime understands in v1 (REQ-01). A manifest declaring
 * any other value is `ENGINE_UNSUPPORTED` — there is no older version to be backward-compatible
 * with yet, so "not exactly 1" and "newer than supported" coincide in practice. */
const SUPPORTED_ENGINE_VERSION = 1;
const ID_PATTERN = /^[a-z0-9-]+$/;
const MAX_ID_LENGTH = 50;

function malformed(message: string): PluginValidationError {
  return { code: "MANIFEST_MALFORMED", file: null, message };
}

/**
 * Validates one already-parsed manifest against BR-02 steps (2)-(6), collecting every applicable
 * error rather than stopping at the first (BR-02: "collect ALL statically-determinable errors").
 * Pure — no I/O, no mutation of `manifest`.
 *
 * @throws Nothing — validation failures are reported via the returned `errors` array, never a
 * thrown error (this function itself cannot fail; a malformed top-level shape, e.g. `manifest`
 * being `null` or an array, is itself a `MANIFEST_MALFORMED` entry in the result, not a throw).
 * @complexity O(fields.length + capabilities.length + hooks.length) — bounded by one manifest's
 * own declared arrays, never by external/unbounded input.
 * @overallScore 100/100
 */
export function validateManifest(
  required: ValidateManifestRequired,
  _optional: ValidateManifestOptional = {}
): ValidateManifestResult {
  const { manifest, folderName, builtInIds } = required;
  const errors: PluginValidationError[] = [];

  if (typeof manifest !== "object" || manifest === null || Array.isArray(manifest)) {
    return { errors: [malformed("tovu.plugin.json must be a JSON object")] };
  }

  // Treat the input as a read-only bag of unknown values — never assigned back into.
  const raw = manifest as Readonly<Record<string, unknown>>;

  for (const key of Object.keys(raw)) {
    if (!ALLOWED_KEYS.has(key)) {
      errors.push(malformed(`unknown manifest key '${key}'`));
    }
  }
  for (const key of REQUIRED_KEYS) {
    if (raw[key] === undefined) {
      errors.push(malformed(`missing required manifest field '${key}'`));
    }
  }

  // --- id: format, folder match, built-in shadowing (BR-02 step 2/3) ---
  const id = typeof raw.id === "string" ? raw.id : undefined;
  if (raw.id !== undefined && id === undefined) {
    errors.push(malformed("'id' must be a string"));
  }
  if (id !== undefined) {
    if (!ID_PATTERN.test(id) || id.length < 1 || id.length > MAX_ID_LENGTH) {
      errors.push(malformed(`id '${id}' must match ${ID_PATTERN} and be 1-${MAX_ID_LENGTH} characters`));
    }
    if (id !== folderName) {
      errors.push({
        code: "ID_FOLDER_MISMATCH",
        file: null,
        message: `manifest id '${id}' does not match its install folder name '${folderName}'`,
      });
    }
    if (builtInIds.some((builtInId) => builtInId.toLowerCase() === id.toLowerCase())) {
      errors.push({
        code: "SHADOWS_BUILT_IN",
        file: null,
        message: `id '${id}' shadows an existing built-in plugin id`,
      });
    }
  }

  // --- engine (BR-02 step 2) ---
  if (raw.engine !== undefined) {
    if (typeof raw.engine !== "number" || !Number.isInteger(raw.engine) || raw.engine < 1) {
      errors.push(malformed("'engine' must be a positive integer"));
    } else if (raw.engine !== SUPPORTED_ENGINE_VERSION) {
      errors.push({
        code: "ENGINE_UNSUPPORTED",
        file: null,
        message: `engine ${raw.engine} is not supported by this runtime (supports ${SUPPORTED_ENGINE_VERSION})`,
      });
    }
  }

  // --- tier (BR-02 step 2, ADR-024 §1 / 1.1.1 fix) ---
  if (raw.tier !== undefined && (typeof raw.tier !== "string" || !VALID_TIERS.has(raw.tier as PluginTier))) {
    errors.push(malformed(`tier '${String(raw.tier)}' must be one of tier-1 | tier-2 | tier-3`));
  }

  // --- capabilities (BR-02 step 4, REQ-04) ---
  const capabilities = Array.isArray(raw.capabilities) ? raw.capabilities : [];
  if (raw.capabilities !== undefined && !Array.isArray(raw.capabilities)) {
    errors.push(malformed("'capabilities' must be an array"));
  }
  for (const capability of capabilities) {
    if (typeof capability !== "string" || !VALID_CAPABILITIES.has(capability as PluginCapability)) {
      errors.push({
        code: "CAPABILITY_UNKNOWN",
        file: null,
        message: `capability '${String(capability)}' is outside the v1 vocabulary`,
      });
    }
  }

  // --- hooks (BR-02 step 5, REQ-05, INV-06 anti-hook-soup) ---
  const hooks = Array.isArray(raw.hooks) ? raw.hooks : [];
  if (raw.hooks !== undefined && !Array.isArray(raw.hooks)) {
    errors.push(malformed("'hooks' must be an array"));
  }
  for (const hook of hooks) {
    if (typeof hook !== "string" || !VALID_HOOKS.has(hook)) {
      errors.push({ code: "HOOK_UNKNOWN", file: null, message: `hook point '${String(hook)}' is not declared by core` });
    }
  }

  // --- fields (BR-02 step 6, REQ-06) ---
  const fields = Array.isArray(raw.fields) ? raw.fields : [];
  if (raw.fields !== undefined && !Array.isArray(raw.fields)) {
    errors.push(malformed("'fields' must be an array"));
  }
  for (const field of fields) {
    if (typeof field !== "object" || field === null) {
      errors.push(malformed("each 'fields' entry must be an object"));
      continue;
    }
    const decl = field as Readonly<Record<string, unknown>>;
    const expectedPrefix = `ext.${id ?? ""}.`;
    if (typeof decl.path !== "string" || !decl.path.startsWith(expectedPrefix) || decl.path.length <= expectedPrefix.length) {
      errors.push({
        code: "FIELD_PATH_INVALID",
        file: null,
        message: `field path '${String(decl.path)}' must be namespaced to this plugin's own id ('${expectedPrefix}*')`,
      });
    }
    if (typeof decl.type !== "string" || !VALID_FIELD_TYPES.has(decl.type)) {
      errors.push(malformed(`field '${String(decl.path)}' has an unrecognized type '${String(decl.type)}'`));
    }
    if (decl.queryable === true) {
      errors.push({
        code: "QUERYABLE_UNSUPPORTED_V1",
        file: null,
        message: `field '${String(decl.path)}' declares queryable:true, unsupported in v1 (OQ-04)`,
      });
    }
  }

  return { errors };
}
/**
 * @file `buildCapabilityScopedSdk()` — builds the per-load `PluginSdk` handle (SPEC-005 REQ-04;
 * CIC U-003, `ESCALATE_SECURITY`).
 *
 * Purpose:
 * REQ-04: "the SDK object handed to the plugin exposes ONLY the granted surface. A plugin
 * invoking a surface it did not declare fails at the SDK boundary (`CAPABILITY_DENIED`)."
 *
 * **CIC U-003 (Binding, ESCALATE_SECURITY):** a naive reading of REQ-04 could satisfy "exposes
 * only the granted surface" by simply OMITTING ungranted properties (`sdk.content = granted ?
 * {...} : undefined`). That is the wrong implementation — AC-05's contract requires a classified,
 * catchable `CAPABILITY_DENIED` error, not a bare `TypeError` from calling a method on
 * `undefined`. This function must therefore always expose a callable at every one of the three
 * v1 capability positions (`content.read`, `content.extend`, `addFilter`) — granted capabilities
 * get the real implementation (delegating to `coreDeps`), ungranted capabilities get a stub that
 * SYNCHRONOUSLY throws a typed `CapabilityDeniedError` naming the missing capability. Any
 * deviation from "always present, never absent" requires a recorded
 * `[CIC_DEVIATION_APPROVED]` entry — see
 * `reports/pipeline/005-plugin-system/critical-internal-constraints.md` U-003.
 *
 * Built fresh per plugin load (never a shared module-level singleton, ADR Decision item 2) — a
 * new `PluginSdk` object is constructed for every `loadPlugin()` call, closing over that one
 * plugin's own `pluginId` and granted capability set only.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-009, CIC U-003). Signature and JSDoc are
 * design-frozen; `buildCapabilityScopedSdk()` returns fresh per-plugin delegates for granted
 * capabilities and present, typed-denial stubs for every ungranted surface.
 */
import type { BeforeSaveFilter, ContentEntryDraft, PluginSdk } from "../../../packages/sdk/src/index.js";
import type { HOOK_CONTENT_ENTRY_BEFORE_SAVE } from "../../../packages/sdk/src/index.js";
import type { PluginCapability } from "./manifest.js";

/** Thrown synchronously when a plugin invokes an SDK surface it did not declare a capability for
 * (REQ-04, INV-02). Classified so `hook-registry.ts` can catch it specifically and map the
 * containing content operation to `PLUGIN_HOOK_FAILED` (BR-07), distinct from any other thrown
 * error a plugin's own code might raise. */
export class CapabilityDeniedError extends Error {
  readonly pluginId: string;
  readonly capability: PluginCapability;

  constructor(pluginId: string, capability: PluginCapability) {
    super(`plugin '${pluginId}' invoked '${capability}' without declaring it in its manifest capabilities`);
    this.name = "CapabilityDeniedError";
    this.pluginId = pluginId;
    this.capability = capability;
  }
}

/** The three real, plugin-instance-scoped callbacks `capability-sdk.ts` wraps with capability
 * gating. Supplied by the caller (the loader, at load time, closing over that specific plugin
 * load's `hook-registry.ts` state) — this module never reaches into `hook-registry.ts` directly. */
export interface CapabilityScopedSdkCoreDeps {
  /** Backing implementation for the granted `content.read()` surface. */
  getCurrentEntry(): Readonly<ContentEntryDraft>;
  /** Backing implementation for the granted `content.extend()` surface — writes into this
   * plugin's own `ext.{pluginId}.{field}` namespace (validated by BR-06 at the caller). */
  writeExtField(field: string, value: string | number | boolean): void;
  /** Backing implementation for the granted `addFilter()` surface. */
  attachFilter(hookName: typeof HOOK_CONTENT_ENTRY_BEFORE_SAVE, filter: BeforeSaveFilter): void;
}

export interface BuildCapabilityScopedSdkRequired {
  readonly pluginId: string;
  /** The manifest's declared capability set (already validated against the v1 vocabulary by
   * `validateManifest()` — this function trusts its input is well-formed capability strings). */
  readonly capabilities: readonly PluginCapability[];
  readonly coreDeps: CapabilityScopedSdkCoreDeps;
}

export type BuildCapabilityScopedSdkOptional = {}

/**
 * Builds one plugin's capability-scoped `PluginSdk` handle. Every one of the three v1 surfaces is
 * always present on the returned object (CIC U-003) — granted surfaces delegate to `coreDeps`,
 * ungranted surfaces are stubs that throw `CapabilityDeniedError` when invoked (never at build
 * time — the stub itself is a normal, present function; only CALLING it throws).
 *
 * @throws Nothing at build time. The returned object's ungranted-surface stubs throw
 * `CapabilityDeniedError` synchronously when invoked by the plugin.
 * @complexity O(1) — three capability checks, trivially small and bounded regardless of
 * plugin-declared array length (the vocabulary itself is fixed-size at exactly three).
 */
export function buildCapabilityScopedSdk(
  required: BuildCapabilityScopedSdkRequired,
  _optional: BuildCapabilityScopedSdkOptional = {}
): PluginSdk {
  const { pluginId, capabilities, coreDeps } = required;
  const granted = new Set<PluginCapability>(capabilities);

  /**
   * Wraps one capability-gated surface: returns `real` when `capability` is granted, otherwise a
   * stub that synchronously throws `CapabilityDeniedError` when invoked. CIC U-003's binding
   * property — every surface is always a present, callable function, never an absent property.
   */
  function gate<Fn extends (...args: never[]) => unknown>(capability: PluginCapability, real: Fn): Fn {
    if (granted.has(capability)) {
      return real;
    }
    return ((..._args: never[]) => {
      throw new CapabilityDeniedError(pluginId, capability);
    }) as unknown as Fn;
  }

  return {
    content: {
      read: gate("content.read", () => coreDeps.getCurrentEntry()),
      extend: gate("content.extend", (field: string, value: string | number | boolean) =>
        coreDeps.writeExtField(field, value)
      ),
    },
    addFilter: gate("hooks.attach", (hookName: typeof HOOK_CONTENT_ENTRY_BEFORE_SAVE, filter: BeforeSaveFilter) =>
      coreDeps.attachFilter(hookName, filter)
    ),
  };
}

/**
 * @file `loadPlugin()` — the BR-01 ordered load pipeline (SPEC-005 REQ-03; CIC U-001, `ESCALATE_SECURITY`).
 *
 * Purpose:
 * The single most security-critical unit in this feature (Implementation Outline C-008's own File
 * Map note). BR-01 defines the following five steps; `loadPlugin()` currently implements steps
 * (1)-(3) in this EXACT order, short-circuiting on the first failure:
 *   (1) verify every packaged file against `manifest.integrity` (mismatch ⇒ `INTEGRITY_FAILED`)
 *   (2) check `manifest.sdkRange` is satisfied by the runtime `@tovu/sdk` version
 *       (miss ⇒ `SDK_RANGE_UNSATISFIED`, status `incompatible`)
 *   (3) dynamic `import()` the entry file (absent/unresolvable ⇒ `CODE_ENTRY_MISSING`)
 *   (4) build a capability-scoped SDK (`capability-sdk.ts`) and invoke the plugin's `setup()` —
 *       not yet called from `loadPlugin()`
 *   (5) attach the plugin's declared hooks via `hook-registry.ts` — not yet called from
 *       `loadPlugin()`; the attach half is implemented separately as `attachLoadedPlugin()`
 *
 * **CIC U-001 (Binding, ESCALATE_SECURITY):** steps (1) and (2) must BOTH complete successfully
 * before step (3) ever runs. A tampered or `sdkRange`-incompatible plugin's code must NEVER be
 * evaluated, even transiently at module-eval time. Any deviation from this ordering requires a
 * recorded `[CIC_DEVIATION_APPROVED]` entry — see
 * `reports/pipeline/005-plugin-system/critical-internal-constraints.md` U-001 before changing the
 * statement order below.
 *
 * Test seams (deliberate, approved — CIC's Verification Surface Rule prefers an observable seam
 * over asserting call-graph shape): `importModule` and `computeFileHash` are injectable so the
 * certified test suite can substitute a spy import function to prove step (3) was never reached
 * for a rejected plugin, without depending on a real dynamic-import/module-resolution environment.
 * Real callers (loader's actual production wiring) omit both and get the real `import()`/SHA-256
 * behavior.
 *
 * Architectural role:
 * TDD-certified implementation of steps (1)-(3) (implementation outline C-008, CIC U-001).
 * Signature and JSDoc are design-frozen; `loadPlugin()` verifies integrity and SDK compatibility
 * before importing code, returning classified expected failures. Steps (4)-(5) remain the
 * documented wiring gap described above and at the successful return path below.
 *
 * **Added 2026-08-04 (ADR-057 Decision 2.1):** `attachLoadedPlugin()`, below `loadPlugin()` in this
 * file, is the real (not stub) extraction of step (5)'s previously-dead attach logic, widened to a
 * `"glue"` source. `loadPlugin()` itself is unchanged — see `attachLoadedPlugin`'s own doc comment
 * for what is and is not covered by the extraction.
 */
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import path from "node:path";

import * as semver from "semver";

import { buildCapabilityScopedSdk, type CapabilityScopedSdkCoreDeps } from "./capability-sdk.js";
import type { PluginDiscoveryRecord } from "./discovery.js";
import type { AttachmentSource, HookRegistry, HookRegistryFieldDecl } from "./hook-registry.js";
import type { PluginManifest } from "./manifest.js";
import type { BeforeSaveFilter, Plugin } from "../../../packages/sdk/src/index.js";

/**
 * The runtime's own installed `@tovu/sdk` version, used for the sdkRange check (step 2) when a
 * caller doesn't supply `runtimeSdkVersion` explicitly. `@tovu/sdk`'s own `exports` map
 * deliberately blocks a deep import of its `package.json` (ADR-005 rule 1: public surface = the
 * pinned runtime exports only), so this cannot be resolved through the package itself — it is a
 * plain constant that must be bumped alongside `packages/sdk/package.json`'s own `version` field.
 * Every certified test supplies `runtimeSdkVersion` explicitly, so this default is exercised only
 * by real production/dev boot, never by the certified suite.
 */
const DEFAULT_RUNTIME_SDK_VERSION = "0.1.0";

/** A packaged artifact's file layout is fixed (ADR-004): `tovu.plugin.json` + `server/index.mjs` at
 * the plugin root. `entryPath` is always `<pluginRoot>/server/index.mjs`, so the root two
 * directories up from it is where `manifest.integrity`'s relative file paths resolve from. */
function derivePluginRoot(entryPath: string): string {
  return path.dirname(path.dirname(entryPath));
}

async function defaultComputeFileHash(absoluteFilePath: string): Promise<string> {
  const bytes = await readFile(absoluteFilePath);
  return `sha256-${createHash("sha256").update(bytes).digest("hex")}`;
}

export interface LoadPluginRequired {
  /** The plugin's already-discovered, statically-valid record (a plugin with a non-`valid` static
   * `status` must never reach `loadPlugin` at all — that guard lives in the caller, BR-05). */
  readonly record: PluginDiscoveryRecord;
  readonly manifest: PluginManifest;
  /** Absolute filesystem path (or, for a built-in, an in-process module identifier) to the
   * plugin's entry point — the exact thing step (3) `import()`s. */
  readonly entryPath: string;
  /** Per-load core handles composed by the application root. `loadPlugin()` owns the imported
   * module and therefore owns building the capability-scoped SDK passed to its `setup()` call;
   * the root owns what each granted handle actually delegates to. */
  readonly coreDeps: CapabilityScopedSdkCoreDeps;
}

export interface LoadPluginOptional {
  /** The runtime's own `@tovu/sdk` version, checked against `manifest.sdkRange` in step (2).
   * Defaults to the runtime's real installed SDK version when omitted. */
  readonly runtimeSdkVersion?: string;
  /** Test seam (approved, CIC U-001 Verification Surface): overrides step (3)'s dynamic import.
   * Defaults to real `import()`. */
  readonly importModule?: (entryPath: string) => Promise<unknown>;
  /** Test seam: overrides step (1)'s per-file SHA-256 computation. Defaults to real hashing of
   * the file at the given absolute path. */
  readonly computeFileHash?: (absoluteFilePath: string) => Promise<string>;
}

export type PluginLoadFailureReason =
  | "INTEGRITY_FAILED"
  | "SDK_RANGE_UNSATISFIED"
  | "CODE_ENTRY_MISSING"
  | "PLUGIN_EXPORT_INVALID"
  | "PLUGIN_SETUP_FAILED";

export type PluginEnableFailureReason = PluginLoadFailureReason | "PLUGIN_HOOK_NOT_ATTACHED" | "PLUGIN_HOOK_ATTACH_FAILED";

/** Raised by the composition root after converting `loadPlugin()`'s expected early-return result
 * into the enable path's error channel. HTTP maps this to `PLUGIN_LOAD_FAILED`; agent tools receive
 * the same typed error directly. */
export class PluginLoadError extends Error {
  readonly pluginId: string;
  readonly reason: PluginEnableFailureReason;

  constructor(pluginId: string, reason: PluginEnableFailureReason, options?: { cause?: unknown }) {
    super(`plugin '${pluginId}' failed to load (${reason})`, options);
    this.name = "PluginLoadError";
    this.pluginId = pluginId;
    this.reason = reason;
  }
}

export type LoadPluginResult =
  | { readonly loaded: true }
  | {
      readonly loaded: false;
      readonly reason: PluginLoadFailureReason;
    };

/** `definePlugin()`'s runtime return shape. A plain `{ setup() {} }` export is deliberately not
 * accepted: only the SDK helper's opaque `{ definition }` wrapper is a valid plugin ABI value. */
function readDefinedPlugin(moduleValue: unknown): Plugin | null {
  if (typeof moduleValue !== "object" || moduleValue === null) return null;
  const candidate = (moduleValue as { default?: unknown }).default;
  if (typeof candidate !== "object" || candidate === null) return null;
  const definition = (candidate as { definition?: unknown }).definition;
  if (typeof definition !== "object" || definition === null) return null;
  return typeof (definition as { setup?: unknown }).setup === "function" ? (candidate as Plugin) : null;
}

/**
 * Executes BR-01's 5-step ordered pipeline for one plugin. See CIC U-001 above for the binding
 * ordering constraint this function's statement order must never invert.
 *
 * @throws Never for an expected pipeline failure (those are reported via the returned `reason`);
 * may propagate an unexpected infrastructure error (e.g. a real filesystem I/O failure unrelated
 * to integrity mismatch).
 * @complexity O(file count) for integrity hashing; the `import()`/`setup()` cost beyond that is
 * plugin-defined and unbounded — no latency budget is specified (ADR `scalability` axis, a
 * disclosed open gap, not a defect of this function).
 */
export async function loadPlugin(
  required: LoadPluginRequired,
  _optional: LoadPluginOptional = {}
): Promise<LoadPluginResult> {
  const { record, manifest, entryPath, coreDeps } = required;
  const importModule = _optional.importModule ?? ((p: string) => import(p));
  const computeFileHash = _optional.computeFileHash ?? defaultComputeFileHash;
  const runtimeSdkVersion = _optional.runtimeSdkVersion ?? DEFAULT_RUNTIME_SDK_VERSION;

  // --- CIC U-001-ORD1: step (1), integrity, MUST complete successfully before step (2)/(3). ---
  const pluginRoot = derivePluginRoot(entryPath);
  for (const [relativeFilePath, expectedHash] of Object.entries(manifest.integrity)) {
    let actualHash: string;
    try {
      actualHash = await computeFileHash(path.join(pluginRoot, relativeFilePath));
    } catch {
      return { loaded: false, reason: "INTEGRITY_FAILED" };
    }
    if (actualHash !== expectedHash) {
      return { loaded: false, reason: "INTEGRITY_FAILED" };
    }
  }

  // --- CIC U-001-ORD1: step (2), sdkRange, MUST complete successfully before step (3). ---
  if (!semver.satisfies(runtimeSdkVersion, manifest.sdkRange)) {
    return { loaded: false, reason: "SDK_RANGE_UNSATISFIED" };
  }

  // --- Step (3): only now, after both prior checks pass, is the plugin's code ever evaluated. ---
  let importedModule: unknown;
  try {
    importedModule = await importModule(entryPath);
  } catch {
    return { loaded: false, reason: "CODE_ENTRY_MISSING" };
  }

  // --- Step (4): validate the `definePlugin()` export, build the per-load gated SDK, run setup. ---
  const plugin = readDefinedPlugin(importedModule);
  if (!plugin) {
    return { loaded: false, reason: "PLUGIN_EXPORT_INVALID" };
  }

  const sdk = buildCapabilityScopedSdk({
    pluginId: record.id,
    capabilities: manifest.capabilities as readonly import("./manifest.js").PluginCapability[],
    coreDeps,
  });
  try {
    await plugin.definition.setup(sdk);
  } catch {
    return { loaded: false, reason: "PLUGIN_SETUP_FAILED" };
  }

  // Step (5) remains composition-owned: setup's gated `addFilter()` handle captures the filter in
  // the caller's `coreDeps`; only after this successful return does the root call the shared
  // `attachLoadedPlugin()` path below. That split prevents a late setup failure from leaving a
  // partially-attached filter behind.
  return { loaded: true };
}

export interface AttachLoadedPluginRequired {
  /** The plugin/glue-module id `hookRegistry.attach()` files this attachment under. */
  readonly pluginId: string;
  /** Who attached this filter — widened by ADR-057 Decision 3 to include `"glue"`, so Site Glue's
   * content-lifecycle attachment point can call this function directly rather than forking it. */
  readonly source: AttachmentSource;
  /** The live registry this load's filter attaches to — one long-lived instance per process
   * (`hook-registry.ts`'s own doc comment), supplied by the caller, never constructed here. */
  readonly hookRegistry: HookRegistry;
  /** The filter obtained from step (4) — i.e. whatever the caller's own `setup()` invocation (with
   * a capability-scoped SDK gating `hooks.attach`) produced. This function does not invoke `setup()`
   * itself: the SDK shape a `setup()` call receives differs by caller (plugin-runtime's own 3-member
   * `PluginCapability` vocabulary for real plugins; Site Glue's 8-member `GlueCapability` vocabulary
   * for glue modules), so building and gating that SDK stays the caller's responsibility. What is
   * genuinely shared — and was genuinely dead before this extraction — is the attach step itself. */
  readonly filter: BeforeSaveFilter;
  readonly declaredFields: readonly HookRegistryFieldDecl[];
}

export type AttachLoadedPluginOptional = {};

/**
 * The real (not stub) extraction of `loadPlugin()`'s dead step (5) — ADR-057 Decision 2.1. Attaches
 * one already-obtained filter to the given hook registry under `(pluginId, source)`, widened beyond
 * `loader.ts`'s original `"built-in" | "site"` scope to also accept `"glue"`. Before ADR-057, no
 * production code ever called `hookRegistry.attach()` at all (verified by grep, see `hook-registry.ts`'s
 * corrected header) — Site Glue's content-lifecycle attachment point is this function's first real
 * caller; a future fix to `loadPlugin()`'s own dead steps (4)-(5) is expected to call this same
 * function from its real activation path rather than re-implementing the attach step a second time.
 *
 * @throws Nothing of its own — propagates whatever `hookRegistry.attach()` itself throws (today,
 * nothing; `attach()` is a plain `Map.set`).
 * @complexity O(1) — a single delegated call, no iteration or I/O of its own.
 * @overallScore 100/100
 */
export function attachLoadedPlugin(
  required: AttachLoadedPluginRequired,
  _optional: AttachLoadedPluginOptional = {}
): void {
  const { pluginId, source, hookRegistry, filter, declaredFields } = required;
  hookRegistry.attach(pluginId, source, filter, declaredFields);
}
/**
 * @file `createHookRegistry()` / `runBeforeSave()` — composes enabled plugins' `content.entry.
 * beforeSave` filters, merges `ext`, fail-closed (SPEC-005 REQ-05/REQ-06; BR-04/BR-06/BR-07;
 * CIC U-004, no escalation marker).
 *
 * Purpose:
 * The concrete adapter for `BeforeSaveHookPort` (`src/features/post/post.ts`'s contract). Keeping
 * this composition logic here — not in `post.ts` — is what keeps `post.ts` plugin-ignorant
 * (Module Map). `activation.ts` calls `.detach()` on disable.
 *
 * **Corrected 2026-08-04 (ADR-057 Decision 2.1):** this comment previously claimed `loader.ts`
 * calls `.attach()` on this registry as each plugin's `setup()` runs. That was false — `loadPlugin()`
 * (`loader.ts`) has never called `.attach()`; steps 4-5 of BR-01 were left unwired, documented but
 * dead, and no other production code called it either (verified: `grep -rn "hookRegistry\.attach"
 * src --include=*.ts`, excluding tests, returned only this file's own now-corrected doc comment).
 * `loader.ts` exports `attachLoadedPlugin()`, the real (not stub) extraction of that dead logic's
 * attach half, widened to accept a `"glue"` source. Site Glue's content-lifecycle attachment point
 * is `attachLoadedPlugin`'s first production caller; `loadPlugin()` itself still does not call it —
 * a future SPEC-005 fix for its own activation path is expected to call the same function, per
 * ADR-057 Decision 2.1, rather than re-inventing this wiring a second time.
 *
 * **CIC U-004 (Binding, no escalation marker — bounded blast radius via SPEC-001's revert):**
 * `runBeforeSave()` must fully resolve (returning the merged patch) or throw before its caller
 * (`post.ts`) constructs the final `PostRecord` passed to `deps.repo.save()`. There is exactly one
 * `repo.save()` call per `createPost`/`updatePost` invocation, and it must never be reached if
 * this function throws (BR-06 same-transaction requirement; BR-07/EC-10 fail-closed: no partial
 * write, no change set on failure). This module's own responsibility ends at "resolve or throw
 * before returning" — `post.ts` is responsible for not calling `repo.save()` on the throw path.
 *
 * Composition order is TB-01 (built-ins first by id ascending, then site plugins by id
 * ascending) — the SAME order `PLUGINS_LIST` uses. Each plugin writes only its own
 * `ext.{pluginId}` namespace (BR-04), so composition order does not create write conflicts, but
 * the ordering is still fixed and deterministic (not incidental) because later filters observe
 * earlier filters' already-merged `ext` values on the entry snapshot they receive.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-010, CIC U-004). Signature and JSDoc are
 * design-frozen; `runBeforeSave()` orders attached filters, gives each an isolated entry snapshot,
 * validates each declared-field patch, and returns the merged per-plugin `ext` object fail-closed.
 */
import type { JsonObject } from "@jini-ai/cms/core";
import type { BeforeSaveFilter, ContentEntryDraft } from "../../../packages/sdk/src/index.js";

/** Who attached a given filter — extended by ADR-057 Decision 3 with `"glue"`, ranked after
 * `"site"` in {@link compareTb01}. Exported so `loader.ts`'s `attachLoadedPlugin()` and any other
 * caller share this one source of truth for the vocabulary rather than re-declaring the union. */
export type AttachmentSource = "built-in" | "site" | "glue";

/** Thrown (and caught by the caller, mapped to 500 `PLUGIN_HOOK_FAILED`) when a filter throws,
 * triggers `CapabilityDeniedError`, or returns an invalid `ext` write (BR-07/EC-10). */
export class PluginHookFailedError extends Error {
  readonly pluginId: string;

  constructor(pluginId: string, message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "PluginHookFailedError";
    this.pluginId = pluginId;
  }
}

/** One field this plugin declared in its manifest (BR-06's validation target — the merge step
 * rejects a returned patch key/value that doesn't match a declared field). */
export interface HookRegistryFieldDecl {
  readonly path: string; // "ext.{pluginId}.{field}"
  readonly type: "string" | "integer" | "number" | "boolean";
}

/** Default recovery policy: tolerate two transient failures, quarantine on the third consecutive
 * failure. Composition may inject a different positive integer per runtime instance. */
export const DEFAULT_PLUGIN_FAILURE_THRESHOLD = 3;

export interface PluginQuarantineEvent {
  readonly pluginId: string;
  readonly workspaceId: string;
  readonly consecutiveFailures: number;
  readonly reason: string;
}

export interface CreateHookRegistryOptions {
  readonly failureThreshold?: number;
  /** Persistence/action port supplied by composition. Absent keeps the registry's legacy
   * fail-closed-only behavior (used by isolated consumers that have no activation repository). */
  readonly onQuarantine?: (event: PluginQuarantineEvent) => Promise<void>;
}

export interface HookRegistry {
  /** Registers one currently-enabled, successfully-loaded plugin's filter (BR-01 step 5). Safe to
   * call again for the same `pluginId` — a second `attach` for an id already attached replaces
   * the prior registration (re-enable after disable, or a loader retry). */
  attach(
    pluginId: string,
    source: AttachmentSource,
    filter: BeforeSaveFilter,
    declaredFields: readonly HookRegistryFieldDecl[]
  ): void;
  /** Removes a plugin's filter (disable, BR-05) — its `ext` data is untouched (INV-03); only the
   * filter stops firing on subsequent saves. */
  detach(pluginId: string): void;
  /** Implements `BeforeSaveHookPort` — the sole surface `post.ts` depends on. */
  runBeforeSave(entry: Readonly<ContentEntryDraft>): Promise<JsonObject>;
}

/** One plugin's currently-attached registration. */
interface Attachment {
  readonly source: AttachmentSource;
  readonly filter: BeforeSaveFilter;
  readonly declaredFields: readonly HookRegistryFieldDecl[];
}

/** TB-01's rank per source, ADR-057 Decision 3's additive third stage: built-ins (0), then site
 * plugins (1), then glue modules (2) — id-ascending within each rank (`compareTb01` below). */
const SOURCE_RANK: Readonly<Record<AttachmentSource, number>> = { "built-in": 0, site: 1, glue: 2 };

/**
 * TB-01 comparator: built-ins before site plugins before glue modules, id-ascending within each
 * group. Shared with `discovery.ts`'s own ordering rule for the `built-in`/`site` ranks (PLUGINS_LIST
 * uses the same order) so those two never diverge; the `glue` rank has no discovery-time analogue
 * since glue modules are never listed by `discovery.ts` (ADR-057 Decision 6 — a separate tier).
 */
function compareTb01(a: readonly [string, Attachment], b: readonly [string, Attachment]): number {
  const rankDiff = SOURCE_RANK[a[1].source] - SOURCE_RANK[b[1].source];
  if (rankDiff !== 0) return rankDiff;
  return a[0].localeCompare(b[0]);
}

/** The four JSON-primitive field types BR-06's declared-field vocabulary supports. */
function matchesDeclaredType(value: unknown, type: HookRegistryFieldDecl["type"]): boolean {
  switch (type) {
    case "integer":
      return typeof value === "number" && Number.isInteger(value);
    case "number":
      return typeof value === "number";
    case "string":
      return typeof value === "string";
    case "boolean":
      return typeof value === "boolean";
    default:
      return false;
  }
}

/** Last dot-segment of a declared `ext.{pluginId}.{field}` path — the field name a returned patch
 * key is checked against. */
function fieldNameOf(declaredPath: string): string {
  const segments = declaredPath.split(".");
  return segments[segments.length - 1] ?? declaredPath;
}

/**
 * Creates a fresh, empty hook registry (no plugins attached). Each process has exactly one
 * long-lived instance, constructed once at composition-root time and shared between `loader.ts`
 * (attach/detach) and `post.ts` (via `BeforeSaveHookPort`, `runBeforeSave` only).
 *
 * @complexity `attach`/`detach` are O(1) (Map operations). `runBeforeSave` is
 * O(attached-plugin-count · own-declared-field-count) for merge/validation bookkeeping, plus each
 * plugin's own filter cost (unbounded, plugin-defined — no latency budget exists, ADR scalability
 * axis, a disclosed gap).
 * @overallScore 100/100
 */
export function createHookRegistry(options: CreateHookRegistryOptions = {}): HookRegistry {
  const failureThreshold = options.failureThreshold ?? DEFAULT_PLUGIN_FAILURE_THRESHOLD;
  if (!Number.isInteger(failureThreshold) || failureThreshold < 1) {
    throw new RangeError("plugin failure threshold must be a positive integer");
  }

  const attachments = new Map<string, Attachment>();
  const consecutiveFailures = new Map<string, Map<string, number>>();

  function clearFailures(pluginId: string, workspaceId?: string): void {
    if (workspaceId !== undefined) {
      const workspaceFailures = consecutiveFailures.get(workspaceId);
      workspaceFailures?.delete(pluginId);
      if (workspaceFailures?.size === 0) consecutiveFailures.delete(workspaceId);
      return;
    }
    for (const [workspace, workspaceFailures] of consecutiveFailures) {
      workspaceFailures.delete(pluginId);
      if (workspaceFailures.size === 0) consecutiveFailures.delete(workspace);
    }
  }

  async function recordFailure(
    pluginId: string,
    workspaceId: string,
    failure: PluginHookFailedError
  ): Promise<void> {
    if (!options.onQuarantine) return;

    const workspaceFailures = consecutiveFailures.get(workspaceId) ?? new Map<string, number>();
    const next = (workspaceFailures.get(pluginId) ?? 0) + 1;
    workspaceFailures.set(pluginId, next);
    consecutiveFailures.set(workspaceId, workspaceFailures);
    if (next < failureThreshold) return;

    // Recover the process first: the triggering save remains fail-closed, but all later saves see
    // the attachment gone even while durable activation state is being recorded.
    detach(pluginId);
    try {
      await options.onQuarantine({
        pluginId,
        workspaceId,
        consecutiveFailures: next,
        reason: failure.message,
      });
    } catch (error) {
      throw new PluginHookFailedError(
        pluginId,
        `${failure.message}; automatic quarantine persistence failed: ${
          error instanceof Error ? error.message : String(error)
        }`,
        { cause: error }
      );
    }
  }

  function attach(
    pluginId: string,
    source: AttachmentSource,
    filter: BeforeSaveFilter,
    declaredFields: readonly HookRegistryFieldDecl[]
  ): void {
    clearFailures(pluginId);
    attachments.set(pluginId, { source, filter, declaredFields });
  }

  function detach(pluginId: string): void {
    attachments.delete(pluginId);
    clearFailures(pluginId);
  }

  async function runBeforeSave(entry: Readonly<ContentEntryDraft>): Promise<JsonObject> {
    const ordered = [...attachments.entries()].sort(compareTb01);
    const merged: Record<string, JsonObject> = {};

    for (const [pluginId, attachment] of ordered) {
      const snapshot: ContentEntryDraft = structuredClone({
        ...entry,
        ext: { ...entry.ext, ...merged },
      });
      const ctx = { pluginId, workspaceId: entry.workspaceId };

      try {
        let patch: unknown;
        try {
          patch = await attachment.filter(snapshot, ctx);
        } catch (error) {
          throw new PluginHookFailedError(
            pluginId,
            `plugin '${pluginId}' content.entry.beforeSave filter failed: ${
              error instanceof Error ? error.message : String(error)
            }`,
            { cause: error }
          );
        }

        if (typeof patch !== "object" || patch === null || Array.isArray(patch)) {
          throw new PluginHookFailedError(
            pluginId,
            `plugin '${pluginId}' returned a non-object ext patch from its beforeSave filter`
          );
        }

        const declaredByField = new Map(attachment.declaredFields.map((f) => [fieldNameOf(f.path), f]));
        const pluginPatch: Record<string, JsonObject[string]> = {};

        for (const [field, value] of Object.entries(patch as Record<string, unknown>)) {
          const decl = declaredByField.get(field);
          if (!decl) {
            throw new PluginHookFailedError(
              pluginId,
              `plugin '${pluginId}' returned undeclared ext field '${field}' (FIELD_PATH_INVALID)`
            );
          }
          if (!matchesDeclaredType(value, decl.type)) {
            throw new PluginHookFailedError(
              pluginId,
              `plugin '${pluginId}' returned ext field '${field}' with a value not matching its declared type '${decl.type}' (FIELD_TYPE_MISMATCH)`
            );
          }
          pluginPatch[field] = value as JsonObject[string];
        }

        merged[pluginId] = pluginPatch;
        clearFailures(pluginId, entry.workspaceId);
      } catch (error) {
        const failure =
          error instanceof PluginHookFailedError
            ? error
            : new PluginHookFailedError(pluginId, `plugin '${pluginId}' beforeSave hook failed`, { cause: error });
        await recordFailure(pluginId, entry.workspaceId, failure);
        throw failure;
      }
    }

    return merged;
  }

  return { attach, detach, runBeforeSave };
}

