/** Executable metadata for one compiled-in plugin. Discovery consumes only `manifest`; the enable
 * callback consumes the import seam after integrity/sdkRange checks. Site-artifact sources can use
 * the same shape once their install-dir resolver is composed here. */
export interface PluginRuntimeSource extends BuiltInPluginSource {
  readonly source: "built-in";
  readonly entryPath: string;
  readonly importModule: (entryPath: string) => Promise<unknown>;
}

interface InvocationState {
  readonly entry: Readonly<ContentEntryDraft>;
  readonly writes: Record<string, string | number | boolean>;
}

export interface ComposePluginRuntimeRequired {
  readonly workspaceId: string;
  readonly clock: ClockPort;
  readonly activationRepo: PluginActivationRepoPort;
  readonly sources: readonly PluginRuntimeSource[];
  /** Consecutive hook failures before quarantine. Omitted uses the registry default. */
  readonly failureThreshold?: number;
}

export interface PluginRuntimeBindings {
  readonly hookRegistry: HookRegistry;
  readonly discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  readonly onPluginEnabled: (pluginId: string) => Promise<void>;
  readonly onPluginDisabled: (pluginId: string) => void;
  readonly beforeSaveHook: HookRegistry["runBeforeSave"];
}

/**
 * Server-layer composition for SPEC-005's runtime half. The application roots own the concrete
 * activation repo/source list; this helper builds the per-load core handles, delegates module
 * ownership/setup to `loadPlugin()`, and performs the one shared attach operation only after setup
 * has completed successfully.
 */
export function composePluginRuntime(required: ComposePluginRuntimeRequired): PluginRuntimeBindings {
  const { activationRepo, clock, sources } = required;
  const hookRegistry = createHookRegistry({
    ...(required.failureThreshold === undefined ? {} : { failureThreshold: required.failureThreshold }),
    onQuarantine: async (input) => {
      await quarantinePlugin({ deps: { clock, repo: activationRepo }, input });
    },
  });
  const discoverPlugins = () => discoverPluginRuntimePlugins({ builtIns: sources });

  async function onPluginEnabled(pluginId: string): Promise<void> {
    const source = sources.find((candidate) => candidate.manifest.id === pluginId);
    const record = (await discoverPlugins()).find((candidate) => candidate.id === pluginId);
    if (!source || !record) {
      throw new PluginLoadError(pluginId, "PLUGIN_EXPORT_INVALID");
    }

    const invocation = new AsyncLocalStorage<InvocationState>();
    let capturedFilter: BeforeSaveFilter | null = null;

    const coreDeps = {
      getCurrentEntry(): Readonly<ContentEntryDraft> {
        const state = invocation.getStore();
        if (!state) throw new Error(`plugin '${pluginId}' called content.read outside a beforeSave hook`);
        return state.entry;
      },
      writeExtField(field: string, value: string | number | boolean): void {
        const state = invocation.getStore();
        if (!state) throw new Error(`plugin '${pluginId}' called content.extend outside a beforeSave hook`);
        state.writes[field] = value;
      },
      attachFilter(hookName: typeof HOOK_CONTENT_ENTRY_BEFORE_SAVE, filter: BeforeSaveFilter): void {
        if (hookName !== HOOK_CONTENT_ENTRY_BEFORE_SAVE || !source.manifest.hooks.includes(hookName)) {
          throw new Error(`plugin '${pluginId}' attempted to attach undeclared hook '${String(hookName)}'`);
        }
        if (capturedFilter) {
          throw new Error(`plugin '${pluginId}' attempted to attach more than one beforeSave filter`);
        }

        capturedFilter = async (entry, ctx) => {
          const state: InvocationState = { entry, writes: {} };
          return invocation.run(state, async () => {
            const returned = await filter(entry, ctx);
            if (Object.keys(state.writes).length === 0) return returned;
            if (typeof returned !== "object" || returned === null || Array.isArray(returned)) return returned;
            return { ...state.writes, ...returned };
          });
        };
      },
    };

    const result = await loadPlugin(
      {
        record,
        manifest: source.manifest,
        entryPath: source.entryPath,
        coreDeps,
      },
      { importModule: source.importModule }
    );
    if (!result.loaded) {
      throw new PluginLoadError(pluginId, result.reason);
    }

    const filter = capturedFilter as BeforeSaveFilter | null;
    if (source.manifest.hooks.includes(HOOK_CONTENT_ENTRY_BEFORE_SAVE) && filter === null) {
      throw new PluginLoadError(pluginId, "PLUGIN_HOOK_NOT_ATTACHED");
    }
    if (filter === null) return;

    try {
      attachLoadedPlugin({
        pluginId,
        source: source.source,
        hookRegistry,
        filter,
        declaredFields: source.manifest.fields,
      });
    } catch (error) {
      hookRegistry.detach(pluginId);
      throw new PluginLoadError(pluginId, "PLUGIN_HOOK_ATTACH_FAILED", { cause: error });
    }
  }

  function onPluginDisabled(pluginId: string): void {
    hookRegistry.detach(pluginId);
  }

  return {
    hookRegistry,
    discoverPlugins,
    onPluginEnabled,
    onPluginDisabled,
    beforeSaveHook: (entry) => hookRegistry.runBeforeSave(entry),
  };
}
/**
 * @file `setPluginEnabled()` / `getActivation()` — gateway-backed enable/disable feature functions
 * (SPEC-005 REQ-07; BR-05; AC-02/AC-13; INV-03/INV-05).
 *
 * Purpose:
 * Mirrors `src/features/presentation/presentation.ts`'s `setActiveTheme`/`getPresentationSettings`
 * shape exactly (Module Map) — a plain feature function, validated and typed-error-throwing, that
 * the ROUTE layer (`src/server/routes/admin/plugins/set-enabled.ts`, C-016) wraps in
 * `executeCommand` (mirrors `admin/posts/update.ts`'s `executeCommand`-wrapped shape, per the
 * ADR's API/Event Contract Summary) — NOT wrapped here. This function itself performs BR-05's
 * three-step precondition evaluation and, on success, upserts the `PluginActivationRecord` and
 * (on enable) invokes the injected load hook / (on disable) the injected unload hook — it does not
 * call the gateway itself.
 *
 * `ext.{pluginId}` data is never touched by either transition (INV-03) — this module has no
 * dependency on `posts.ext` at all, by construction (it only ever touches `plugin_activations`).
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-011/C-012). Signatures and JSDoc are
 * design-frozen; `setPluginEnabled()` runs BR-05's three-step evaluation, upserts the activation
 * row, then invokes the injected `onEnabled`/`onDisabled` side effect. If that side effect throws
 * after the row was saved, `restoreOnSideEffectFailure()` compensates — restoring the prior record,
 * or deleting it for a first-time enable/disable — best-effort, before rethrowing the original
 * error unmasked. `getActivation()` is a thin read. Both satisfy
 * `__tests__/integration/activation.integration.test.ts`.
 */
import type { ClockPort, UUID } from "@jini-ai/cms/core";
import type { PluginDiscoveryRecord } from "./discovery.js";

/** `plugin_activations` row (durable, behind the gateway) — state.spec.md §2. */
export interface PluginActivationRecord {
  readonly pluginId: string;
  readonly workspaceId: UUID;
  /** The active (enabled) installed version — the "active pointer" (ADR-004). */
  readonly version: string;
  readonly enabled: boolean;
  readonly updatedAt: string;
  /** Present only while automatic quarantine is active. A normal enable/disable save omits these
   * fields, which clears the durable marker and makes re-enable the operator recovery action. */
  readonly quarantinedAt?: string;
  readonly quarantineReason?: string;
  readonly quarantineFailureCount?: number;
}

/** Persistence contract — shaped identically to `PresentationSettingsRepoPort` (rule-of-two, two
 * adapters from day one: `repo.memory.ts` / `repo.sqlite.ts`). */
export interface PluginActivationRepoPort {
  getActivation(required: { workspaceId: UUID; pluginId: string }): Promise<PluginActivationRecord | null>;
  save(record: PluginActivationRecord): Promise<void>;
  deleteActivation(required: { workspaceId: UUID; pluginId: string }): Promise<void>;
  /** Every row across every workspace — used by discovery's `enabled` projection and by any
   * future migration, mirrors `PresentationSettingsRepoPort.listAll`. */
  listAll(): Promise<PluginActivationRecord[]>;
}

/**
 * Restores the repo to its pre-transition state after a side-effect hook (`onEnabled`/
 * `onDisabled`) throws: writes back the record that existed before this transition, or — for a
 * first-time enable/disable where no prior record existed — deletes the row `setPluginEnabled`
 * just created. Best-effort: a compensation failure must never mask the original side-effect
 * error, so this swallows its own failure and lets the caller rethrow the original.
 *
 * @complexity O(1) — one repo write.
 */
async function restoreOnSideEffectFailure(
  repo: PluginActivationRepoPort,
  existing: PluginActivationRecord | null,
  target: { workspaceId: UUID; pluginId: string }
): Promise<void> {
  try {
    if (existing) {
      await repo.save(existing);
    } else {
      await repo.deleteActivation(target);
    }
  } catch {
    // Compensation is best-effort; its failure must not mask the original side-effect error.
  }
}

export class PluginNotFoundError extends Error {}
export class PluginInvalidError extends Error {}
export class PluginIncompatibleError extends Error {}

export interface SetPluginEnabledDeps {
  clock: ClockPort;
  repo: PluginActivationRepoPort;
  /** The current discovery snapshot — used to evaluate BR-05's "id present in discovery" and
   * (when enabling) "status 'valid'" preconditions. Callers pass a fresh `discoverPlugins()`
   * result; this function does not call discovery itself (keeps it a pure state-transition step
   * over an already-known snapshot, easier to test deterministically). */
  discovery: readonly PluginDiscoveryRecord[];
  /** Invoked on a successful enable transition, after the activation row is saved — the actual
   * `loadPlugin()`/hook-attach side effect. Optional so this function stays testable without a
   * real loader; a real composition root always supplies one. */
  onEnabled?: (pluginId: string) => Promise<void>;
  /** Invoked on a successful disable transition — detaches the plugin's hooks
   * (`hook-registry.ts`'s `detach`). Optional for the same testability reason as `onEnabled`. */
  onDisabled?: (pluginId: string) => void;
}

export interface SetPluginEnabledInput {
  readonly workspaceId: UUID;
  readonly pluginId: string;
  readonly enabled: boolean;
}

export interface SetPluginEnabledRequired {
  deps: SetPluginEnabledDeps;
  input: SetPluginEnabledInput;
}

export type SetPluginEnabledOptional = {}

/**
 * BR-05's three-step evaluation: (1) id present in discovery ⇒ else `PluginNotFoundError`;
 * (2) when enabling, discovered `status` is `"valid"` ⇒ else `PluginInvalidError`/
 * `PluginIncompatibleError`; (3) upsert the activation row and invoke the load/unload side
 * effect. Disable has no validity precondition (BR-05) — a plugin that became invalid after being
 * enabled can always still be disabled.
 *
 * @throws {PluginNotFoundError} the plugin id is not present in the given discovery snapshot.
 * @throws {PluginInvalidError} enabling a plugin whose discovered `status` is `"invalid"`.
 * @throws {PluginIncompatibleError} enabling a plugin whose discovered `status` is `"incompatible"`.
 */
export async function setPluginEnabled(
  required: SetPluginEnabledRequired,
  _optional: SetPluginEnabledOptional = {}
): Promise<{ activation: PluginActivationRecord }> {
  const { deps, input } = required;

  const discovered = deps.discovery.find((record) => record.id === input.pluginId);
  if (!discovered) {
    throw new PluginNotFoundError(`plugin '${input.pluginId}' was not found in the current discovery snapshot`);
  }

  if (input.enabled) {
    if (discovered.status === "incompatible") {
      throw new PluginIncompatibleError(`plugin '${input.pluginId}' is incompatible with this runtime's SDK version`);
    }
    if (discovered.status !== "valid") {
      throw new PluginInvalidError(`plugin '${input.pluginId}' failed validation and cannot be enabled`);
    }
  }

  // The active-version pointer only ever advances on a genuine enable (REQ-02's "active pointer");
  // disabling must not silently re-point it to whatever discovery currently reports as latest —
  // it preserves whichever version was actually active (AC-13: disable's version is unchanged
  // from the enable it inverts).
  const existing = await deps.repo.getActivation({ workspaceId: input.workspaceId, pluginId: input.pluginId });
  const version = input.enabled ? discovered.version : (existing?.version ?? discovered.version);

  const activation: PluginActivationRecord = {
    pluginId: input.pluginId,
    workspaceId: input.workspaceId,
    version,
    enabled: input.enabled,
    updatedAt: deps.clock.nowIso(),
  };

  await deps.repo.save(activation);

  const target = { workspaceId: input.workspaceId, pluginId: input.pluginId };

  if (input.enabled) {
    try {
      await deps.onEnabled?.(input.pluginId);
    } catch (error) {
      await restoreOnSideEffectFailure(deps.repo, existing, target);
      throw error;
    }
  } else {
    try {
      deps.onDisabled?.(input.pluginId);
    } catch (error) {
      await restoreOnSideEffectFailure(deps.repo, existing, target);
      throw error;
    }
  }

  return { activation };
}

export interface GetActivationRequired {
  deps: { repo: PluginActivationRepoPort };
  input: { workspaceId: UUID; pluginId: string };
}

export type GetActivationOptional = {}

/** Reads current activation state for projection into `PLUGINS_LIST` (state.spec.md §5). `null`
 * means "never enabled" (treated as disabled), not an error. */
export async function getActivation(
  required: GetActivationRequired,
  _optional: GetActivationOptional = {}
): Promise<PluginActivationRecord | null> {
  return required.deps.repo.getActivation(required.input);
}
/**
 * @file `discoverPlugins()` — enumerate built-in + site plugins with status (SPEC-005 REQ-02/03,
 * EC-08/EC-09, TB-01, DUP-01).
 *
 * Purpose:
 * Read-only enumeration. Scans the install-dir's `plugins/<id>/<version>/` tree (REQ-02) plus the
 * compiled-in built-in registry, performs BR-02 step (1)'s package-level checks (size, disallowed
 * files, `server/index.mjs` presence — see `manifest.ts`'s header for why those checks live here
 * rather than in `validateManifest()`), delegates manifest/identity/capability/hook/field checks to
 * `validateManifest()`, and returns one `PluginDiscoveryRecord` per discovered id with every
 * applicable error recorded — never throws for an individual plugin's own validation failure
 * (errors are data, not control flow; REQ-10/`PLUGINS_LIST` lists every discovered plugin, valid or
 * not).
 *
 * Never `import()`s plugin code — that is `loader.ts`'s job, gated by integrity/`sdkRange` first
 * (BR-01, CIC U-001). Discovery only reads bytes to hash/measure/list them.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-007). Signature and JSDoc are
 * design-frozen; `discoverPlugins()` validates built-ins, selects the latest installed site
 * version per id, records candidate-local errors without aborting discovery, marks duplicate ids,
 * and returns deterministic TB-01 ordering.
 */
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

import * as semver from "semver";

import { validateManifest, type PluginManifest, type PluginTier, type PluginValidationError } from "./manifest.js";

/** A built-in plugin's in-code manifest-equivalent (ADR Decision item 4) — no tarball, no
 * integrity file (compiled-in code is definitionally not tampered), but still validated through
 * the same `validateManifest()` path as a site-installed plugin. */
export interface BuiltInPluginSource {
  readonly manifest: PluginManifest;
}

export interface DiscoverPluginsRequired {
  /** Every compiled-in built-in plugin (REQ-09's `word-count` is the v1 sole member). */
  readonly builtIns: readonly BuiltInPluginSource[];
  /** Absolute path to the site's `plugins/` install directory. Absent ⇒ legacy mode: built-ins
   * only, everything else behaves identically (EC-09, AC-16). */
  readonly installDir?: string;
}

export type DiscoverPluginsOptional = {}

/** In-memory, rebuilt each discovery pass — NOT persisted (state.spec.md §2). Feeds `PLUGINS_LIST`
 * once activation state is projected onto it by the caller (the HTTP route layer, C-016/C-017 —
 * discovery itself does not know about `plugin_activations`). */
export interface PluginDiscoveryRecord {
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly source: "built-in" | "site";
  /** (1.1.2, REQ-10/REQ-18) The plugin's trust tier, projected verbatim from the already-required
   * `PluginManifest.tier` (REQ-01/ADR-024 §1) — mirrors how `source` already passes through
   * unchanged. Optional on this stub type only so pre-existing fixtures in unrelated test files
   * (`activation.integration.test.ts`, `loader.integration.test.ts`) that construct
   * `PluginDiscoveryRecord` literals for concerns unrelated to REQ-10/`PLUGINS_LIST` are not forced
   * to retrofit it; the real `discoverPlugins()` implementation must always populate it (a
   * discovered plugin's manifest always has a validated `tier` by the time a record exists),
   * enforced behaviorally by the dedicated REQ-10 pass-through tests in `plugins-dto.unit.test.ts`
   * / `plugins-http.integration.test.ts`, not by widening this field to non-optional everywhere. */
  readonly tier?: "tier-1" | "tier-2" | "tier-3";
  readonly status: "valid" | "invalid" | "incompatible";
  readonly errors: readonly PluginValidationError[];
}

/**
 * Enumerates every built-in and (when `installDir` is present) site-installed plugin, in TB-01
 * order (built-ins first by id ascending, then site plugins by id ascending). When two installed
 * versions of one site plugin id exist, only the latest-by-semver is included in the result (the
 * other stays dormant on disk, EC-08/AC-09) — the loader (not discovery) is what actually imports
 * the winning version later.
 *
 * @throws Never for an individual plugin's own validation/package failure — that plugin's record
 * simply carries a non-empty `errors[]` and a non-`valid` `status`. May reject for a genuine
 * infrastructure failure (e.g. `installDir` exists but is unreadable due to a permissions error)
 * that is not itself one specific plugin's fault.
 * @complexity O(n) over installed-plugin count, bounded I/O per candidate (one directory listing
 * + manifest read + per-file size stat).
 */
const VALID_TIERS = new Set<PluginTier>(["tier-1", "tier-2", "tier-3"]);
/** v1's loader is exactly ADR-024's Tier-3 reality — used only as a last-resort fallback when a
 * candidate's manifest doesn't parse far enough to carry its own (already-validated-elsewhere)
 * `tier` value, so a discovery record always has a renderable tier (REQ-18/AC-26). */
const FALLBACK_TIER: PluginTier = "tier-3";

/** Safely reads a JSON value's string property, or `undefined` when absent/wrong-typed. */
function readStringField(value: unknown, key: string): string | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const raw = (value as Record<string, unknown>)[key];
  return typeof raw === "string" ? raw : undefined;
}

function readTierField(value: unknown): PluginTier {
  const raw = readStringField(value, "tier");
  return raw !== undefined && VALID_TIERS.has(raw as PluginTier) ? (raw as PluginTier) : FALLBACK_TIER;
}

/** Parses one `tovu.plugin.json` file's bytes; unparseable JSON becomes `null` — `validateManifest`
 * already reports a `MANIFEST_MALFORMED` entry for any non-object value (its own top-level guard),
 * so a parse failure and a wrong-shape object are handled through the exact same code path. */
function parseManifestJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function toDiscoveryRecord(params: {
  id: string;
  name: string;
  version: string;
  source: "built-in" | "site";
  manifestValue: unknown;
  errors: readonly PluginValidationError[];
}): PluginDiscoveryRecord {
  return {
    id: params.id,
    name: params.name,
    version: params.version,
    source: params.source,
    tier: readTierField(params.manifestValue),
    status: params.errors.length === 0 ? "valid" : "invalid",
    errors: params.errors,
  };
}

/** One directory entry directly under `installDir` — a candidate plugin "id slot" that may contain
 * one or more version subdirectories (REQ-02's `plugins/<id>/<version>/` layout). */
async function listInstalledPluginIdFolders(installDir: string): Promise<string[]> {
  try {
    const entries = await readdir(installDir, { withFileTypes: true });
    return entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") return [];
    throw error;
  }
}

/** Picks the latest-by-semver version subdirectory under one id folder (AC-09/EC-08) — the other
 * installed versions stay dormant on disk, never surfaced as a second row. Non-semver directory
 * names sort last (defensive; every certified fixture uses valid semver directory names). */
async function pickLatestVersionFolder(idFolderPath: string): Promise<string | null> {
  const entries = await readdir(idFolderPath, { withFileTypes: true });
  const versionNames = entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);
  if (versionNames.length === 0) return null;

  const sorted = [...versionNames].sort((a, b) => {
    const aValid = semver.valid(a);
    const bValid = semver.valid(b);
    if (aValid && bValid) return semver.rcompare(aValid, bValid);
    if (aValid) return -1;
    if (bValid) return 1;
    return b.localeCompare(a);
  });
  return sorted[0] ?? null;
}

async function discoverOneSiteCandidate(
  installDir: string,
  idFolderName: string,
  builtInIds: readonly string[]
): Promise<PluginDiscoveryRecord | null> {
  const idFolderPath = path.join(installDir, idFolderName);
  const versionFolderName = await pickLatestVersionFolder(idFolderPath);
  if (versionFolderName === null) return null;

  const manifestPath = path.join(idFolderPath, versionFolderName, "tovu.plugin.json");
  let manifestValue: unknown = null;
  let missing = false;
  try {
    manifestValue = parseManifestJson(await readFile(manifestPath, "utf8"));
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code === "ENOENT") {
      missing = true;
    } else {
      throw error;
    }
  }

  const errors: PluginValidationError[] = missing
    ? [{ code: "MANIFEST_MISSING", file: "tovu.plugin.json", message: "tovu.plugin.json was not found" }]
    : [...validateManifest({ manifest: manifestValue, folderName: idFolderName, builtInIds }).errors];

  const id = readStringField(manifestValue, "id") ?? idFolderName;
  const name = readStringField(manifestValue, "name") ?? idFolderName;

  return toDiscoveryRecord({ id, name, version: versionFolderName, source: "site", manifestValue, errors });
}

/** DUP-01 (`ID_DUPLICATE` half — `SHADOWS_BUILT_IN` is already handled per-record inside
 * `validateManifest`, which only ever sees one candidate at a time): a case-insensitive id
 * collision between two SITE plugins can only be detected once every candidate is known, so this
 * runs as a whole-set post-pass over the already-built site records. */
function markCaseInsensitiveDuplicates(records: readonly PluginDiscoveryRecord[]): PluginDiscoveryRecord[] {
  const countByLowerId = new Map<string, number>();
  for (const record of records) {
    const key = record.id.toLowerCase();
    countByLowerId.set(key, (countByLowerId.get(key) ?? 0) + 1);
  }

  return records.map((record) => {
    const isDuplicate = (countByLowerId.get(record.id.toLowerCase()) ?? 0) > 1;
    if (!isDuplicate) return record;

    const errors = [
      ...record.errors,
      { code: "ID_DUPLICATE", file: null, message: `id '${record.id}' collides case-insensitively with another installed site plugin` },
    ];
    return { ...record, errors, status: "invalid" as const };
  });
}

/** TB-01: built-ins first (id ascending), then site plugins (id ascending) — the same ordering
 * `hook-registry.ts`'s composition uses, so `PLUGINS_LIST` and hook-composition order never
 * diverge. */

import { AsyncLocalStorage } from "node:async_hooks";

import type { ClockPort } from "@jini-ai/cms/core";

import type { PluginActivationRepoPort } from "../features/plugin-runtime/activation.js";
import type { BuiltInPluginSource, PluginDiscoveryRecord } from "../features/plugin-runtime/discovery.js";
import { discoverPlugins as discoverPluginRuntimePlugins } from "../features/plugin-runtime/discovery.js";
import { createHookRegistry, type HookRegistry } from "../features/plugin-runtime/hook-registry.js";
import { quarantinePlugin } from "../features/plugin-runtime/quarantine.js";
import {
  attachLoadedPlugin,
  loadPlugin,
  PluginLoadError,
} from "../features/plugin-runtime/loader.js";
import {
  HOOK_CONTENT_ENTRY_BEFORE_SAVE,
  type BeforeSaveFilter,
  type ContentEntryDraft,
} from "../../packages/sdk/src/index.js";

/** Executable metadata for one compiled-in plugin. Discovery consumes only `manifest`; the enable
 * callback consumes the import seam after integrity/sdkRange checks. Site-artifact sources can use
 * the same shape once their install-dir resolver is composed here. */
export interface PluginRuntimeSource extends BuiltInPluginSource {
  readonly source: "built-in";
  readonly entryPath: string;
  readonly importModule: (entryPath: string) => Promise<unknown>;
}

interface InvocationState {
  readonly entry: Readonly<ContentEntryDraft>;
  readonly writes: Record<string, string | number | boolean>;
}

export interface ComposePluginRuntimeRequired {
  readonly workspaceId: string;
  readonly clock: ClockPort;
  readonly activationRepo: PluginActivationRepoPort;
  readonly sources: readonly PluginRuntimeSource[];
  /** Consecutive hook failures before quarantine. Omitted uses the registry default. */
  readonly failureThreshold?: number;
}

export interface PluginRuntimeBindings {
  readonly hookRegistry: HookRegistry;
  readonly discoverPlugins: () => Promise<readonly PluginDiscoveryRecord[]>;
  readonly onPluginEnabled: (pluginId: string) => Promise<void>;
  readonly onPluginDisabled: (pluginId: string) => void;
  readonly beforeSaveHook: HookRegistry["runBeforeSave"];
}

/**
 * Server-layer composition for SPEC-005's runtime half. The application roots own the concrete
 * activation repo/source list; this helper builds the per-load core handles, delegates module
 * ownership/setup to `loadPlugin()`, and performs the one shared attach operation only after setup
 * has completed successfully.
 */
export function composePluginRuntime(required: ComposePluginRuntimeRequired): PluginRuntimeBindings {
  const { activationRepo, clock, sources } = required;
  const hookRegistry = createHookRegistry({
    ...(required.failureThreshold === undefined ? {} : { failureThreshold: required.failureThreshold }),
    onQuarantine: async (input) => {
      await quarantinePlugin({ deps: { clock, repo: activationRepo }, input });
    },
  });
  const discoverPlugins = () => discoverPluginRuntimePlugins({ builtIns: sources });

  async function onPluginEnabled(pluginId: string): Promise<void> {
    const source = sources.find((candidate) => candidate.manifest.id === pluginId);
    const record = (await discoverPlugins()).find((candidate) => candidate.id === pluginId);
    if (!source || !record) {
      throw new PluginLoadError(pluginId, "PLUGIN_EXPORT_INVALID");
    }

    const invocation = new AsyncLocalStorage<InvocationState>();
    let capturedFilter: BeforeSaveFilter | null = null;

    const coreDeps = {
      getCurrentEntry(): Readonly<ContentEntryDraft> {
        const state = invocation.getStore();
        if (!state) throw new Error(`plugin '${pluginId}' called content.read outside a beforeSave hook`);
        return state.entry;
      },
      writeExtField(field: string, value: string | number | boolean): void {
        const state = invocation.getStore();
        if (!state) throw new Error(`plugin '${pluginId}' called content.extend outside a beforeSave hook`);
        state.writes[field] = value;
      },
      attachFilter(hookName: typeof HOOK_CONTENT_ENTRY_BEFORE_SAVE, filter: BeforeSaveFilter): void {
        if (hookName !== HOOK_CONTENT_ENTRY_BEFORE_SAVE || !source.manifest.hooks.includes(hookName)) {
          throw new Error(`plugin '${pluginId}' attempted to attach undeclared hook '${String(hookName)}'`);
        }
        if (capturedFilter) {
          throw new Error(`plugin '${pluginId}' attempted to attach more than one beforeSave filter`);
        }

        capturedFilter = async (entry, ctx) => {
          const state: InvocationState = { entry, writes: {} };
          return invocation.run(state, async () => {
            const returned = await filter(entry, ctx);
            if (Object.keys(state.writes).length === 0) return returned;
            if (typeof returned !== "object" || returned === null || Array.isArray(returned)) return returned;
            return { ...state.writes, ...returned };
          });
        };
      },
    };

    const result = await loadPlugin(
      {
        record,
        manifest: source.manifest,
        entryPath: source.entryPath,
        coreDeps,
      },
      { importModule: source.importModule }
    );
    if (!result.loaded) {
      throw new PluginLoadError(pluginId, result.reason);
    }

    const filter = capturedFilter as BeforeSaveFilter | null;
    if (source.manifest.hooks.includes(HOOK_CONTENT_ENTRY_BEFORE_SAVE) && filter === null) {
      throw new PluginLoadError(pluginId, "PLUGIN_HOOK_NOT_ATTACHED");
    }
    if (filter === null) return;

    try {
      attachLoadedPlugin({
        pluginId,
        source: source.source,
        hookRegistry,
        filter,
        declaredFields: source.manifest.fields,
      });
    } catch (error) {
      hookRegistry.detach(pluginId);
      throw new PluginLoadError(pluginId, "PLUGIN_HOOK_ATTACH_FAILED", { cause: error });
    }
  }

  function onPluginDisabled(pluginId: string): void {
    hookRegistry.detach(pluginId);
  }

  return {
    hookRegistry,
    discoverPlugins,
    onPluginEnabled,
    onPluginDisabled,
    beforeSaveHook: (entry) => hookRegistry.runBeforeSave(entry),
  };
}

