  const { markers } = scanEmbedMarkers(html);
  let out = html;
  for (let i = markers.length - 1; i >= 0; i -= 1) {
    const m = markers[i];
    const replacement = resolve(m);
    if (replacement === undefined) continue;
    out = out.slice(0, m.index) + replacement + out.slice(m.index + m.whole.length);
  }
  return out;
}

/**
